-- Demo readings are stored by the original seed names, so dragging a lesson or
-- sub-lesson does not change which reading it displays. Custom names have no match.
CREATE TABLE courseflow.demo_lesson_content (
    course_title TEXT NOT NULL,
    lesson_name TEXT NOT NULL,
    sub_lesson_name TEXT NOT NULL,
    lesson_order INTEGER NOT NULL,
    sub_lesson_order INTEGER NOT NULL,
    title TEXT NOT NULL,
    objective TEXT NOT NULL,
    paragraph_one TEXT NOT NULL,
    paragraph_two TEXT NOT NULL,
    example TEXT NOT NULL,
    exercise TEXT NOT NULL,
    solution TEXT NOT NULL,
    PRIMARY KEY (course_title, lesson_name, sub_lesson_name)
);

