INSERT INTO courseflow.demo_lesson_content (course_title, lesson_name, sub_lesson_name, lesson_order, sub_lesson_order, title, objective, paragraph_one, paragraph_two, example, exercise, solution)
VALUES
    ('Digital Marketing Basics', 'Lesson 1', 'Sub-lesson 1', 1, 1, 'Audience and Marketing Goals', 'เชื่อมกลุ่มเป้าหมายกับเป้าหมายการสื่อสารได้', 'การตลาดเริ่มจากรู้ว่าต้องการช่วยใครและอยากให้เกิดพฤติกรรมใด การมียอดเห็นมากอาจไม่ช่วยหากผู้เห็นไม่เกี่ยวข้องกับข้อเสนอหรือยังไม่เข้าใจคุณค่า', 'เลือกกลุ่มหนึ่ง ระบุปัญหาและขั้นตอนตัดสินใจ แล้วตั้งเป้าหมายที่วัดได้ในช่วงเวลาหนึ่ง แยกการรับรู้ออกจากการสมัครหรือการกลับมาใช้ซ้ำ', 'คอร์สเริ่มเขียนโปรแกรมอาจมุ่งคนที่อยากทำเว็บแรก เป้าหมายทดลองคือผู้สนใจเปิดอ่านรายละเอียดบท ไม่ใช่ยอดติดตามทุกประเภท', 'เขียนกลุ่มเป้าหมาย เป้าหมายพฤติกรรม และตัวชี้วัดสำหรับบทเรียนทดลองฟรี', 'กลุ่ม: ผู้เริ่มต้นที่ยังไม่เคยเขียนโค้ด พฤติกรรม: อ่านบทและลองโจทย์ ตัวชี้วัด: จำนวนหรือสัดส่วนที่ทำโจทย์ โดยกำหนดวิธีนับและช่วงเวลา'),
    ('Digital Marketing Basics', 'Lesson 2', 'Sub-lesson 1', 2, 1, 'Customer Journey and Channels', 'เลือกช่องทางตามขั้นตอนตัดสินใจได้', 'คนที่เพิ่งรู้จักกับคนที่กำลังเปรียบเทียบต้องการข้อมูลต่างกัน ช่องทางควรเหมาะกับคำถามในแต่ละช่วง ไม่จำเป็นต้องใช้ทุกช่องทางพร้อมกัน', 'วางช่วงรู้จัก พิจารณา ลงมือ และกลับมาใช้ จับคู่เนื้อหาและช่องทางกับคำถามแต่ละช่วง แล้วตรวจความต่อเนื่องของข้อความเมื่อผู้ใช้ย้ายช่องทาง', 'โพสต์ตัวอย่างงานช่วยให้รู้จัก หน้าเนื้อหาคอร์สช่วยเปรียบเทียบ และข้อความยืนยันหลังสมัครช่วยเริ่มเรียน ทั้งหมดควรบอกข้อมูลตรงกัน', 'จับคู่ช่องทางและข้อมูลกับสามช่วงก่อนสมัครคอร์ส', 'รู้จักผ่านตัวอย่างบทสั้น พิจารณาจากหลักสูตรและข้อกำหนดพื้นฐาน ตัดสินใจจากราคาและเงื่อนไขสมัคร เลือกช่องทางตามพฤติกรรมที่ตรวจพบของกลุ่มเป้าหมาย'),
    ('Digital Marketing Basics', 'Lesson 3', 'Sub-lesson 1', 3, 1, 'Content Planning', 'วางเนื้อหาที่ช่วยตอบคำถามผู้ชมได้', 'แผนเนื้อหาที่ดีเชื่อมคำถามผู้ชมกับสารหลักและการกระทำถัดไป การโพสต์บ่อยโดยไม่มีเป้าหมายอาจเพิ่มงานโดยไม่ช่วยให้ผู้ชมเข้าใจข้อเสนอ', 'รวบรวมคำถามจริง แบ่งเป็นหัวข้อ แล้วกำหนดวัตถุประสงค์ รูปแบบ เจ้าของ และวันที่ตรวจผล เนื้อหาแต่ละชิ้นควรมีสารหลักที่สรุปได้หนึ่งประโยค', 'หัวข้อยังไม่เคยเขียนโค้ดจะเริ่มอย่างไร อาจใช้บทตัวอย่างที่ทำตามได้และลิงก์ไปดูพื้นฐานที่ต้องเตรียม', 'ร่างเนื้อหาสามชิ้นสำหรับหนึ่งสัปดาห์ พร้อมเป้าหมายแต่ละชิ้น', 'ชิ้นแรกตอบข้อกังวลผู้เริ่มต้น ชิ้นสองสาธิตงานเล็ก ชิ้นสามอธิบายลำดับเรียน ระบุสิ่งที่อยากให้ผู้ชมเข้าใจและตรวจผลหลังเผยแพร่'),
    ('Digital Marketing Basics', 'Lesson 4', 'Sub-lesson 1', 4, 1, 'Search Intent and Useful Pages', 'ออกแบบหน้าให้ตอบเจตนาค้นหาได้', 'เจตนาค้นหาคือสิ่งที่คนต้องการจากการค้น เช่น เรียนรู้วิธีทำ เปรียบเทียบ หรือหาสิ่งเฉพาะ หน้าเว็บควรตอบคำถามนั้นได้จริงแทนการใส่คำซ้ำจำนวนมาก', 'เลือกคำถามหลัก เขียนหัวข้อที่สื่อเนื้อหาตรง จัดคำตอบเป็นส่วนที่อ่านง่าย และให้ลิงก์ที่เกี่ยวข้อง ตรวจว่าชื่อหน้าและเนื้อหาไม่สัญญาเกินสิ่งที่มี', 'คนค้นหาตัวแปรคืออะไรต้องการคำอธิบายและตัวอย่าง หน้าเน้นราคาอย่างเดียวอาจไม่ตอบโจทย์ แม้มีคำว่าตัวแปรอยู่หลายครั้ง', 'ร่างหัวข้อสามส่วนสำหรับบทความเริ่มเรียน UX ต้องรู้อะไรบ้าง', 'UX คืออะไร, ทักษะพื้นฐานที่ใช้, และแบบฝึกหัดเริ่มต้น แต่ละส่วนควรตอบคำถามพร้อมตัวอย่าง ไม่อ้างว่าจะได้อันดับค้นหาแน่นอน'),
    ('Digital Marketing Basics', 'Lesson 5', 'Sub-lesson 1', 5, 1, 'Campaign Measurement', 'คำนวณอัตราพื้นฐานและตีความอย่างระมัดระวังได้', 'อัตราคลิกเท่ากับจำนวนคลิกหารจำนวนการแสดงผล ส่วนอัตราสมัครต้องระบุว่าหารด้วยผู้เข้าชมหรือฐานใด ตัวชี้วัดที่ใช้ตัวหารต่างกันเปรียบเทียบตรง ๆ ไม่ได้', 'กำหนดชื่อเหตุการณ์และวิธีนับก่อนเก็บข้อมูล แยกจำนวนคนจากจำนวนครั้ง และตรวจข้อมูลซ้ำ ใช้ตัวเลขเพื่อหาคำถามต่อ ไม่สรุปสาเหตุจากการเปลี่ยนแปลงเดียว', 'แสดงผล 2000 ครั้ง คลิก 100 ครั้ง ได้อัตราคลิก 5% หากผู้เข้าชม 80 คนสมัคร 8 คน อัตราสมัครต่อผู้เข้าชมคือ 10%', 'แสดงผล 1000 ครั้ง คลิก 40 ครั้ง ผู้เข้าชม 35 คน สมัคร 7 คน คำนวณอัตราคลิกและอัตราสมัครต่อผู้เข้าชม', 'อัตราคลิก 40/1000 = 4% อัตราสมัคร 7/35 = 20% อย่าใช้ 7/40 แล้วเรียกว่าอัตราต่อผู้เข้าชม เพราะคลิกและคนเป็นคนละหน่วย'),
    ('Digital Marketing Basics', 'Lesson 6', 'Sub-lesson 1', 6, 1, 'Experiment and Improve', 'วางการทดลองข้อความโดยกำหนดเกณฑ์ล่วงหน้าได้', 'การทดลองเปรียบเทียบต้องมีคำถามชัดและกลุ่มที่เทียบกันได้ หากเปลี่ยนข้อความ กลุ่มผู้ชม และช่วงเวลาพร้อมกันจะไม่รู้ว่าสิ่งใดทำให้ผลต่าง', 'ตั้งสมมติฐาน เลือกตัวแปรที่จะเปลี่ยน กำหนดตัวชี้วัดและแผนวิเคราะห์ก่อนเริ่ม ตรวจผลข้างเคียง และไม่รีบประกาศผู้ชนะจากข้อมูลเพียงเล็กน้อย', 'ทดลองหัวข้อเน้นผลลัพธ์เทียบกับหัวข้อเน้นจำนวนบท โดยใช้ข้อเสนอและกลุ่มผู้ชมที่เทียบเคียงกัน แล้วดูทั้งการคลิกและการสมัคร', 'ร่างการทดลองหัวข้อหน้าแนะนำคอร์สหนึ่งครั้ง พร้อมข้อจำกัด', 'สมมติฐาน: หัวข้อสร้างเว็บแรกช่วยให้เข้าใจคุณค่ามากกว่า 20 บทเรียน วัดการเข้าไปดูหลักสูตรและการสมัคร กำหนดแผนเก็บข้อมูลก่อน และยอมรับว่าข้อมูลอาจยังไม่พอสรุป'),
    ('Data Analytics Foundations', 'Lesson 1', 'Sub-lesson 1', 1, 1, 'Questions Before Data', 'เปลี่ยนคำถามกว้างเป็นโจทย์วิเคราะห์ได้', 'การวิเคราะห์เริ่มจากการตัดสินใจและคำถาม ข้อมูลจำนวนมากไม่มีประโยชน์หากไม่รู้ว่ากำลังวัดสิ่งใด ควรกำหนดหน่วยวิเคราะห์ กลุ่ม และช่วงเวลาก่อนคำนวณ', 'เขียนคำถามหนึ่งข้อ ระบุตัวชี้วัดและข้อมูลที่ต้องใช้ ตรวจว่าผลแบบใดจะนำไปสู่การตัดสินใจใด และบันทึกสิ่งที่ข้อมูลตอบไม่ได้', 'แทนถามว่าคอร์สดีไหม ถามว่าผู้สมัครรุ่นเดือนนี้เริ่มบทแรกภายใน 7 วันกี่เปอร์เซ็นต์ โดยต้องมีเวลาสมัครและเวลาเริ่มเรียน', 'เปลี่ยนคำถามผู้เรียนชอบอะไรให้เป็นคำถามที่วัดได้หนึ่งข้อ', 'เช่น บทใดมีอัตราเปิดแบบฝึกหัดสูงสุดในรุ่นที่กำหนด แต่การเปิดไม่ยืนยันความชอบ ควรใช้ข้อมูลความคิดเห็นประกอบหากต้องการตอบเรื่องความชอบ'),
    ('Data Analytics Foundations', 'Lesson 2', 'Sub-lesson 1', 2, 1, 'Tables and Data Types', 'ระบุหน่วยของแถวและชนิดของคอลัมน์ได้', 'ตารางหนึ่งควรมีความหมายของหนึ่งแถวชัด เช่น หนึ่งผู้เรียนหรือหนึ่งเหตุการณ์ คอลัมน์อาจเป็นตัวเลข หมวดหมู่ เวลา หรือรหัส การรวมข้อมูลคนละระดับทำให้เกิดการนับซ้ำได้', 'เขียนพจนานุกรมข้อมูล ระบุชนิด หน่วย และค่าที่ว่างได้ ตรวจรหัสที่ควรไม่ซ้ำ และเก็บรหัสที่มีศูนย์นำหน้าเป็นข้อความเมื่อไม่ได้ใช้คำนวณ', 'ตารางการเปิดบทมีหลายแถวต่อผู้เรียน จำนวนแถวจึงไม่ใช่จำนวนผู้เรียน ต้องนับรหัสผู้เรียนไม่ซ้ำหากต้องการจำนวนคน', 'กำหนดชนิดและความหมายของ learner_id, lesson_id และ opened_at', 'รหัสผู้เรียนและรหัสบทเป็นตัวระบุ ส่วน opened_at เป็นเวลาเปิดพร้อมข้อตกลงเขตเวลา หนึ่งแถวคือหนึ่งเหตุการณ์ ไม่ใช่ผู้เรียนหนึ่งคน'),
    ('Data Analytics Foundations', 'Lesson 3', 'Sub-lesson 1', 3, 1, 'Cleaning Data', 'ตรวจข้อมูลซ้ำ ว่าง และรูปแบบไม่ตรงกันได้', 'การทำความสะอาดข้อมูลต้องรักษาความหมาย ไม่ใช่ลบทุกแถวที่ดูแปลก ค่าว่างอาจหมายถึงยังไม่เกิดเหตุการณ์หรือระบบไม่ได้เก็บ ซึ่งส่งผลต่อการตีความต่างกัน', 'เก็บต้นฉบับไว้ กำหนดกฎแปลงและเหตุผล ตรวจข้อมูลซ้ำด้วยคีย์ที่เหมาะสม แล้วเทียบจำนวนแถวก่อนหลัง บันทึกสิ่งที่ลบหรือแก้เพื่อให้ทำซ้ำได้', 'ชื่อคอร์สที่มีช่องว่างท้ายอาจรวมเป็นหมวดเดียวกันได้ แต่ผู้เรียนชื่อเหมือนกันไม่ควรถูกลบเป็นคนซ้ำหากรหัสต่างกัน', 'เสนอวิธีจัดการคะแนนว่างโดยไม่แทนทุกค่าด้วยศูนย์ทันที', 'ตรวจว่าค่าว่างหมายถึงยังไม่ส่งงานหรือข้อมูลหาย แยกสถานะและรายงานจำนวนค่าว่าง การแทนศูนย์ควรใช้เฉพาะเมื่อกฎคะแนนกำหนดเช่นนั้น'),
    ('Data Analytics Foundations', 'Lesson 4', 'Sub-lesson 1', 4, 1, 'Descriptive Statistics', 'เลือกค่าเฉลี่ยหรือมัธยฐานตามข้อมูลได้', 'ค่าเฉลี่ยคือผลรวมหารจำนวนข้อมูล ส่วนมัธยฐานคือค่ากลางหลังเรียงลำดับ ค่าเฉลี่ยไวต่อค่าที่สูงหรือต่ำมาก จึงควรดูการกระจายและจำนวนข้อมูลประกอบ', 'ตรวจหน่วยและค่าว่าง เรียงข้อมูลเพื่อดูค่าผิดปกติ แล้วคำนวณทั้งค่ากลางและช่วง เปรียบเทียบว่าตัวเลขใดอธิบายคำถามได้เหมาะกว่า', 'เวลาเรียน 10, 10, 15, 15, 100 นาที มีค่าเฉลี่ย 30 นาทีและมัธยฐาน 15 นาที ค่าทั้งสองตอบมุมมองต่างกัน', 'คำนวณค่าเฉลี่ยและมัธยฐานของ 2, 3, 3, 4, 18', 'ผลรวม 30 หาร 5 ได้ค่าเฉลี่ย 6 มัธยฐานคือค่าลำดับที่ 3 เท่ากับ 3 ค่า 18 ดึงค่าเฉลี่ยขึ้น ควรตรวจว่าค่านี้เป็นข้อมูลจริงหรือข้อผิดพลาด'),
    ('Data Analytics Foundations', 'Lesson 5', 'Sub-lesson 1', 5, 1, 'Filtering and Aggregation', 'จัดกลุ่มและเลือกตัวหารให้ตรงคำถามได้', 'การกรองเลือกแถวที่เกี่ยวข้อง ส่วนการรวมกลุ่มสรุปตามหมวด เช่น คอร์สหรือสัปดาห์ ต้องใช้เงื่อนไขเดียวกันเมื่อเปรียบเทียบ และระวังเฉลี่ยค่าเฉลี่ยของกลุ่มขนาดต่างกัน', 'กำหนดกลุ่มและช่วงเวลาก่อนนับ เก็บทั้งผลรวมและจำนวนรายการ หากรวมค่าเฉลี่ยหลายกลุ่มให้ถ่วงด้วยจำนวนข้อมูลของแต่ละกลุ่ม', 'ห้อง A มี 2 คนเฉลี่ย 10 คะแนน ห้อง B มี 8 คนเฉลี่ย 20 คะแนน ค่าเฉลี่ยรวมคือ (2×10+8×20)/10 = 18 ไม่ใช่ 15', 'กลุ่ม A มี 3 คนเฉลี่ย 60 กลุ่ม B มี 7 คนเฉลี่ย 80 จงหาค่าเฉลี่ยรวม', 'รวมคะแนนเท่ากับ 3×60 + 7×80 = 740 หาร 10 คน ได้ 74 ต้องใช้จำนวนคนถ่วงน้ำหนักเพราะกลุ่มไม่เท่ากัน'),
    ('Data Analytics Foundations', 'Lesson 6', 'Sub-lesson 1', 6, 1, 'Joining Tables', 'เชื่อมตารางโดยระวังแถวเพิ่มและข้อมูลหายได้', 'การ join เชื่อมแถวผ่านคีย์ร่วมกัน ความสัมพันธ์หนึ่งต่อหลายทำให้ข้อมูลด้านหนึ่งปรากฏซ้ำได้ Inner join เก็บคู่ที่ตรงกัน ส่วน left join เก็บทุกแถวฝั่งซ้ายแม้ไม่มีคู่', 'ระบุคีย์และความสัมพันธ์ ตรวจความไม่ซ้ำของคีย์ก่อนเชื่อม แล้วตรวจจำนวนแถวและค่าที่จับคู่ไม่สำเร็จหลังเชื่อม อย่านับจำนวนคนจากแถวที่ขยายแล้วโดยตรง', 'ผู้เรียน 1 คนมีเหตุการณ์เปิดบท 3 ครั้ง เมื่อ join ผู้เรียนกับเหตุการณ์จะได้ 3 แถว การนับแถวเป็นคนจึงเกินจริง', 'ต้องการรายชื่อผู้เรียนทุกคนรวมคนที่ไม่เคยเปิดบท ควรเชื่อมแบบใด', 'ใช้ผู้เรียนเป็นฝั่งซ้ายและ left join กับเหตุการณ์ คนไม่เคยเปิดบทจะมีค่าเหตุการณ์ว่าง ตรวจจำนวนรหัสผู้เรียนไม่ซ้ำให้เท่ากับต้นทาง'),
    ('Data Analytics Foundations', 'Lesson 7', 'Sub-lesson 1', 7, 1, 'Exploring Patterns', 'ตรวจรูปแบบและค่าผิดปกติก่อนสรุปได้', 'การสำรวจข้อมูลช่วยตั้งสมมติฐาน ไม่ได้ยืนยันเหตุและผล รูปแบบรวมอาจซ่อนความต่างระหว่างกลุ่ม และค่าผิดปกติอาจเป็นทั้งเหตุการณ์จริงหรือข้อผิดพลาด', 'ดูการกระจายตามเวลาและกลุ่ม ตรวจช่วงที่ข้อมูลขาด แล้วตั้งคำถามต่อ เปรียบเทียบช่วงเวลาที่มีโอกาสเกิดเหตุการณ์เท่ากัน เช่น รุ่นที่มีเวลาเรียนครบเท่ากัน', 'รุ่นที่สมัครเมื่อวานย่อมมีเวลาเรียนจบน้อยกว่ารุ่นเดือนก่อน การเทียบอัตราจบทันทีอาจทำให้ตีความหลักสูตรผิด', 'เสนอสิ่งที่ต้องตรวจก่อนสรุปว่ายอดเรียนจบลดลงในเดือนล่าสุด', 'ตรวจเวลาที่ผู้เรียนมีให้เรียน จำนวนผู้สมัคร การเก็บเหตุการณ์ที่เปลี่ยน และส่วนผสมของคอร์ส จากนั้นเปรียบเทียบกลุ่มที่ติดตามครบช่วงเวลาเดียวกัน'),
    ('Data Analytics Foundations', 'Lesson 8', 'Sub-lesson 1', 8, 1, 'Choosing Charts', 'เลือกกราฟให้ตรงการเปรียบเทียบได้', 'กราฟแท่งเหมาะกับเปรียบเทียบหมวด กราฟเส้นเหมาะกับแนวโน้มตามเวลา และ scatter plot ช่วยดูความสัมพันธ์ระหว่างสองตัวเลข ชนิดกราฟควรตามคำถาม ไม่ใช่ความสวย', 'ระบุชื่อแกน หน่วย และช่วงเวลา ใช้สเกลที่ไม่บิดความต่าง กราฟแท่งโดยทั่วไปควรเริ่มจากศูนย์เพื่อให้ความยาวเปรียบเทียบได้ และไม่ใช้สีเกินจำเป็น', 'เปรียบเทียบจำนวนผู้เรียนของ 5 คอร์สใช้แท่ง ส่วนจำนวนผู้เรียนรายสัปดาห์ใช้เส้นโดยเว้นระยะเวลาสม่ำเสมอ', 'เลือกกราฟสำหรับคะแนนแต่ละคอร์สและความสัมพันธ์เวลาเรียนกับคะแนน พร้อมข้อควรระวัง', 'คะแนนสรุปแต่ละคอร์สใช้แท่งพร้อมจำนวนผู้เรียน ส่วนเวลาและคะแนนรายคนใช้ scatter plot ความสัมพันธ์ที่เห็นไม่ยืนยันว่าเพิ่มเวลาแล้วคะแนนจะเพิ่มเสมอ'),
    ('Data Analytics Foundations', 'Lesson 9', 'Sub-lesson 1', 9, 1, 'Correlation and Experiments', 'แยกความสัมพันธ์ออกจากเหตุและผลได้', 'ตัวแปรสองตัวเปลี่ยนไปด้วยกันอาจมีปัจจัยอื่นอธิบาย เช่น คนมีแรงจูงใจสูงทั้งเรียนมากและทำคะแนนดี การสังเกตความสัมพันธ์อย่างเดียวจึงไม่ยืนยันสาเหตุ', 'เสนอคำอธิบายทางเลือก ตรวจวิธีเก็บและการเลือกกลุ่ม หากต้องการประเมินผลของการเปลี่ยนแปลงให้วางการทดลองที่มีกลุ่มเทียบเหมาะสมและเกณฑ์วิเคราะห์ล่วงหน้า', 'ผู้ใช้ที่เปิดแบบฝึกหัดได้คะแนนสูงกว่า อาจเป็นเพราะตั้งใจเรียนมากอยู่แล้ว ไม่ใช่ผลจากแบบฝึกหัดทั้งหมด', 'ยกปัจจัยแทรกหนึ่งอย่างเมื่อพบว่าผู้ดูวิดีโอนานสอบผ่านมากกว่า', 'พื้นฐานเดิมหรือแรงจูงใจอาจมีผลต่อทั้งเวลาชมและคะแนน ต้องตรวจหรือออกแบบการทดลองเพิ่มเติมก่อนอ้างว่าเพิ่มเวลาชมทำให้ผ่าน'),
    ('Data Analytics Foundations', 'Lesson 10', 'Sub-lesson 1', 10, 1, 'Communicating Findings', 'เล่าข้อค้นพบพร้อมฐานการคำนวณและข้อจำกัดได้', 'ข้อสรุปที่ใช้งานได้ต้องตอบคำถาม บอกหลักฐาน และแสดงขอบเขตความมั่นใจ ตัวเลขที่ไม่มีหน่วย ตัวหาร หรือช่วงเวลาอาจทำให้ผู้ฟังเข้าใจผิดแม้คำนวณถูก', 'เริ่มจากสิ่งที่พบ ตามด้วยวิธีคำนวณและข้อจำกัด แล้วระบุการตัดสินใจที่รองรับ แยกสิ่งที่ควรทำทันทีออกจากสมมติฐานที่ต้องตรวจเพิ่ม', 'ผู้เรียนรุ่นนี้ 30 จาก 50 คนเริ่มภายใน 7 วัน เท่ากับ 60% ชัดกว่าพูดว่าการเริ่มเรียนอยู่ที่ 60% โดยไม่มีฐาน', 'เขียนสรุปจากผู้เรียน 80 คน มี 20 คนทำโจทย์จบ โดยยังไม่รู้สาเหตุของการหยุด', 'ในกลุ่มและช่วงเวลาที่กำหนด 20/80 หรือ 25% ทำโจทย์จบ ยังอธิบายสาเหตุไม่ได้ เสนอตรวจจุดหยุดและสัมภาษณ์ก่อนเปลี่ยนความยากของโจทย์'),
    ('Leadership Essentials', 'Lesson 1', 'Sub-lesson 1', 1, 1, 'Shared Goals and Expectations', 'กำหนดเป้าหมายและความคาดหวังร่วมกับทีมได้', 'ผู้นำช่วยให้ทีมเข้าใจผลลัพธ์ที่ต้องการ เหตุผล และขอบเขตการตัดสินใจ การแจกงานโดยไม่อธิบายเป้าหมายทำให้คนทำครบรายการแต่ผลอาจไม่ตอบโจทย์', 'คุยเป้าหมายร่วมกัน ระบุเจ้าของงาน เกณฑ์สำเร็จ และเวลาตรวจความคืบหน้า ให้ทีมทวนความเข้าใจและเปิดพื้นที่ชี้ข้อจำกัดก่อนตกลง', 'แทนคำว่าปรับหน้าเรียนให้ดีขึ้น ใช้ผู้เรียนใหม่ต้องหาบทแรกและเปิดอ่านได้โดยไม่ต้องถาม พร้อมกำหนดวิธีตรวจ', 'เขียนข้อตกลงงานสำหรับเตรียมคอร์สทดลองหนึ่งคอร์ส', 'ระบุผู้รับผิดชอบ ขอบเขตเนื้อหา เกณฑ์ตรวจความถูกต้อง วันส่งร่าง และคนให้ข้อเสนอแนะ รวมวิธีแจ้งเมื่อพบอุปสรรคก่อนถึงกำหนด'),
    ('Leadership Essentials', 'Lesson 2', 'Sub-lesson 1', 2, 1, 'Listening and Clear Communication', 'ตรวจความเข้าใจก่อนตอบหรือแก้ปัญหาได้', 'การฟังเชิงรุกคือพยายามเข้าใจสิ่งที่อีกฝ่ายหมายถึง รวมทั้งบริบทและข้อกังวล การทวนความเข้าใจช่วยเปิดโอกาสให้แก้สิ่งที่เราตีความผิด', 'ถามคำถามเปิด ฟังให้จบ แล้วสรุปสิ่งที่ได้ยินโดยไม่เพิ่มเจตนา ถามว่าอีกฝ่ายต้องการให้ช่วยคิด ตัดสินใจ หรือเพียงรับทราบ ก่อนเสนอทางแก้', 'เมื่อเพื่อนบอกว่างานเยอะ อาจหมายถึงลำดับไม่ชัดหรือมีงานเร่งแทรก ควรถามว่างานส่วนไหนทำให้ติดขัด แทนบอกให้บริหารเวลาดีขึ้นทันที', 'ร่างคำตอบต่อเพื่อนร่วมทีมที่บอกว่าไม่ทันกำหนด', 'ขอให้เล่าว่าส่วนใดเหลือและติดอะไร ทวนข้อจำกัด แล้วร่วมกันเลือกปรับขอบเขตหรือหาแรงช่วย สรุปข้อตกลงใหม่ให้ชัด'),
    ('Leadership Essentials', 'Lesson 3', 'Sub-lesson 1', 3, 1, 'Feedback and Coaching', 'ให้ข้อเสนอแนะจากพฤติกรรมที่สังเกตได้', 'ข้อเสนอแนะที่นำไปใช้ได้ระบุสถานการณ์ พฤติกรรม และผลกระทบ แทนการตัดสินบุคลิก Coaching ช่วยให้อีกฝ่ายคิดทางเลือกและลงมือด้วยความเข้าใจของตนเอง', 'ใช้เหตุการณ์เฉพาะ ถามมุมมองอีกฝ่าย แล้วตกลงการทดลองปรับหนึ่งอย่าง กำหนดเวลาติดตามและความช่วยเหลือที่ต้องการ ไม่ทิ้งท้ายด้วยคำแนะนำกว้าง ๆ', 'ในการประชุมเมื่อวานมีการเปลี่ยนงานโดยไม่แจ้งเจ้าของ ทำให้ทำซ้ำ ชัดกว่าพูดว่าคุณสื่อสารไม่ดี', 'เปลี่ยนคำว่าคุณไม่รับผิดชอบเป็นข้อเสนอแนะที่ตรวจสอบได้', 'ระบุงานและกำหนดที่พลาด ผลกระทบที่เกิด แล้วถามอุปสรรค ตกลงว่าจะอัปเดตสถานะเมื่อใด ไม่เหมารวมคุณลักษณะของคนจากเหตุการณ์เดียว'),
    ('Leadership Essentials', 'Lesson 4', 'Sub-lesson 1', 4, 1, 'Delegation and Ownership', 'มอบหมายงานพร้อมอำนาจตัดสินใจที่เหมาะสมได้', 'การมอบหมายไม่ใช่ส่งภาระให้คนอื่น แต่ทำให้ผู้รับมีเป้าหมาย ข้อมูล ทรัพยากร และขอบเขตอำนาจชัด หากต้องขออนุมัติทุกเรื่องความรับผิดชอบจะไม่เกิดจริง', 'ตกลงผลลัพธ์ ข้อจำกัด เรื่องที่ตัดสินใจเองได้ และจุดที่ต้องปรึกษา เลือกจังหวะติดตามตามความเสี่ยงและประสบการณ์ พร้อมให้ความช่วยเหลือโดยไม่ยึดงานกลับทันที', 'มอบหมายเตรียมตัวอย่างบทเรียน โดยให้เลือกกรณีศึกษาได้เอง แต่ต้องให้ผู้เชี่ยวชาญตรวจเนื้อหาก่อนเผยแพร่', 'เขียนขอบเขตอำนาจและจุดตรวจสำหรับคนรับผิดชอบทดสอบคอร์ส', 'เลือกตารางทดสอบและสรุปปัญหาได้เอง แต่การเปลี่ยนเกณฑ์ผ่านหรือเปิดให้ผู้ใช้ทั้งหมดต้องปรึกษา นัดตรวจแผนก่อนเริ่มและผลหลังจบ'),
    ('Leadership Essentials', 'Lesson 5', 'Sub-lesson 1', 5, 1, 'Conflict and Team Reflection', 'จัดการความเห็นต่างโดยกลับมาที่เป้าหมายร่วมได้', 'ความเห็นต่างอาจเกิดจากข้อมูล เป้าหมาย หรือข้อจำกัดไม่ตรงกัน การแยกประเด็นออกจากตัวบุคคลช่วยให้หาทางเลือกได้โดยไม่ทำให้การสนทนาเป็นการกล่าวโทษ', 'ให้แต่ละฝ่ายเล่าข้อกังวล ทวนเป้าหมายร่วม และแยกข้อเท็จจริงจากสมมติฐาน เลือกวิธีตัดสินหรือทดลอง แล้วทบทวนผลและวิธีทำงานหลังเหตุการณ์', 'ฝ่ายหนึ่งอยากเปิดคอร์สเร็ว อีกฝ่ายกังวลข้อผิดพลาด อาจตกลงทดลองกับกลุ่มเล็กหลังตรวจบทหลัก แทนเลือกเร็วหรือคุณภาพอย่างใดอย่างหนึ่ง', 'ออกแบบคำถามทบทวนทีมสามข้อหลังเปิดคอร์สทดลอง', 'สิ่งใดช่วยให้สำเร็จ; จุดใดทำให้งานติดและเพราะอะไร; รอบหน้าจะเปลี่ยนหนึ่งอย่างอะไร ระบุเจ้าของและเวลาตรวจผลของการปรับ'),
    ('Agile Project Management', 'Lesson 1', 'Sub-lesson 1', 1, 1, 'Iterative Delivery', 'แบ่งงานให้ส่งมอบและรับข้อเสนอแนะเป็นรอบได้', 'การทำงานแบบวนรอบลดความไม่แน่นอนด้วยการส่งสิ่งที่ใช้งานได้ทีละส่วน แล้วเรียนรู้จากผลจริง การแบ่งงานเป็นรอบอย่างเดียวไม่ช่วยหากแต่ละรอบยังไม่มีสิ่งที่ตรวจได้', 'กำหนดผลลัพธ์เล็กที่ครบเส้นทางใช้งาน เลือกกลุ่มที่จะลอง และเก็บข้อเสนอแนะก่อนวางรอบถัดไป ปรับขอบเขตตามสิ่งที่เรียนรู้โดยรักษาเป้าหมาย', 'รอบแรกเปิดอ่านบทหนึ่งได้ตั้งแต่รายการถึงเนื้อหา มีประโยชน์ต่อการตรวจมากกว่าทำปุ่มทั้งหมดแต่ยังไม่มีบทให้อ่าน', 'แบ่งการทำระบบเรียนออนไลน์เป็นผลลัพธ์ย่อยสามรอบ', 'เปิดอ่านบทแรกได้ → บันทึกความคืบหน้าได้ → ทำแบบฝึกหัดและดูแนวคำตอบได้ แต่ละรอบต้องระบุผู้ทดลองและเกณฑ์ตรวจ'),
    ('Agile Project Management', 'Lesson 2', 'Sub-lesson 1', 2, 1, 'Backlog and User Stories', 'เขียนงานจากความต้องการและเกณฑ์ยอมรับได้', 'Backlog รวมงานที่อาจช่วยให้ถึงเป้าหมาย ส่วน user story อธิบายว่าใครต้องการอะไรและเพื่ออะไร รายละเอียดสำคัญอยู่ที่การสนทนาและเกณฑ์ยอมรับ ไม่ใช่รูปประโยคเพียงอย่างเดียว', 'เขียนผู้ใช้ การกระทำ และประโยชน์ เพิ่มตัวอย่างพฤติกรรมที่ใช้ตรวจรับ แยกงานที่ใหญ่จนตรวจยากให้เล็กลงโดยยังมีคุณค่าต่อผู้ใช้', 'ผู้เรียนต้องการกลับมาบทที่ค้างเพื่อไม่ต้องค้นใหม่ เกณฑ์คือเปิดคอร์สแล้วเห็นบทที่ยังไม่จบ และไม่เปิดคอร์สที่ไม่มีสิทธิ์', 'เขียน user story และเกณฑ์สองข้อสำหรับปุ่มอ่านจบแล้ว', 'ผู้เรียนต้องการบันทึกบทที่อ่านจบเพื่อรู้ความคืบหน้า เกณฑ์: บันทึกแล้วสถานะเปลี่ยนเมื่อเซิร์ฟเวอร์ตอบสำเร็จ; บันทึกล้มเหลวต้องแจ้งและไม่แสดงว่าสำเร็จ'),
    ('Agile Project Management', 'Lesson 3', 'Sub-lesson 1', 3, 1, 'Priorities and Dependencies', 'เรียงงานโดยคำนึงถึงสิ่งที่ต้องพร้อมก่อน', 'ลำดับงานควรพิจารณาทั้งคุณค่า ความเสี่ยง และสิ่งที่งานอื่นพึ่งพา งานที่เล็กแต่ปลดข้อจำกัดอาจสำคัญกว่างานที่เห็นผลเด่นแต่ยังทำต่อไม่ได้', 'เขียนความสัมพันธ์ระหว่างงาน ระบุข้อไม่แน่นอนที่ควรทดลองก่อน และเลือกเส้นทางขั้นต่ำที่ทำให้ตรวจคุณค่าได้ ลดการเริ่มหลายงานที่รอสิ่งเดียวกัน', 'หน้าเรียนต้องมีโครงสร้างบทและเนื้อหา ส่วนบันทึกความคืบหน้าต้องรู้ผู้เรียนและบท หากยังไม่มีรหัสที่แน่นอนควรตกลงก่อนเชื่อมระบบ', 'เรียงเตรียมเนื้อหา ทำหน้าบทเรียน และทดสอบผู้ใช้ พร้อมอธิบายสิ่งที่ทำคู่กันได้', 'ตกลงรูปแบบเนื้อหาก่อน จากนั้นเขียนเนื้อหาและทำหน้าจอคู่กันด้วยตัวอย่างร่วม ทดสอบเส้นทางเมื่อเชื่อมครบ ไม่รอเขียนทุกบทเพื่อเริ่มตรวจบทแรก'),
    ('Agile Project Management', 'Lesson 4', 'Sub-lesson 1', 4, 1, 'Estimation and Capacity', 'ใช้การประมาณเพื่อวางแผนโดยยอมรับความไม่แน่นอนได้', 'การประมาณคือการคาดการณ์จากข้อมูลที่มี ไม่ใช่คำรับรอง งานที่ไม่เข้าใจควรมีช่วงสำรวจ และความสามารถทีมต้องหักเวลางานประจำ การประชุม และการช่วยเหลือกันด้วย', 'แตกงานให้เข้าใจได้ เปรียบเทียบกับงานที่ผ่านมา ระบุสมมติฐานและช่วงความไม่แน่นอน แล้วเลือกงานเท่าที่ทีมมีโอกาสทำครบ อย่าเพิ่มภาระเพราะตัวเลขดูสวย', 'ทีมมีเวลา 40 ชั่วโมงแต่ต้องดูแลงานประจำ 12 ชั่วโมง จึงเหลือเวลาวางแผนไม่เกิน 28 ชั่วโมงก่อนคิดเผื่อเหตุไม่คาดคิด', 'ทีมมี 30 ชั่วโมง งานประจำ 8 และประชุม 4 เหลือเท่าไร และควรถือว่าแน่นอนหรือไม่', 'เหลือ 18 ชั่วโมงตามสมมติฐาน แต่ยังมีความไม่แน่นอน จึงควรเลือกงานที่เหมาะและระบุสิ่งที่จะเลื่อนหากมีเหตุแทรก'),
    ('Agile Project Management', 'Lesson 5', 'Sub-lesson 1', 5, 1, 'Planning a Work Cycle', 'ตั้งเป้าหมายรอบงานที่ทีมใช้ตัดสินใจได้', 'รอบงานควรมีเป้าหมายร่วมที่อธิบายผลลัพธ์ ไม่ใช่แค่รวมรายการงาน เป้าหมายช่วยให้ทีมปรับรายละเอียดระหว่างทางได้โดยรู้ว่าอะไรสำคัญต่อรอบนี้', 'เลือกเป้าหมาย ตรวจความพร้อมของงานและแรงทีม แล้วตกลงเกณฑ์เสร็จร่วมกัน งานที่ยังมีคำถามสำคัญอาจต้องสำรวจก่อนรับเข้ารอบ', 'เป้าหมายผู้เรียนเปิดอ่านบทและบันทึกจบได้ เชื่อมงานหน้าจอ เนื้อหา และ API เข้าด้วยกัน ทุกส่วนต้องทำงานร่วมกันจึงถือว่าได้ผล', 'เขียนเป้าหมายรอบสำหรับเพิ่มแบบฝึกหัดโดยไม่ใช้รายการงานเป็นเป้าหมาย', 'ผู้เรียนลองโจทย์หลังบทและเปรียบเทียบกับแนวคำตอบได้ เกณฑ์รวมถึงแสดงโจทย์ตรงบท เปิดคำตอบได้ และไม่อ้างว่าส่งตรวจหากยังไม่มีระบบส่ง'),
    ('Agile Project Management', 'Lesson 6', 'Sub-lesson 1', 6, 1, 'Visualizing Work and Blockers', 'ใช้สถานะงานเพื่อช่วยกันแก้อุปสรรคได้', 'กระดานงานทำให้เห็นงานที่กำลังทำ งานรอ และงานเสร็จ จุดประสงค์คือช่วยการไหลของงาน ไม่ใช่ติดตามคนอย่างเดียว งานค้างหลายชิ้นอาจสะท้อนคอขวด', 'กำหนดความหมายของแต่ละสถานะ จำกัดการเริ่มงานใหม่เมื่อมีงานค้าง และระบุผู้ช่วยแก้ blocker การอัปเดตควรบอกสิ่งที่ต้องการความช่วยเหลือและขั้นตอนถัดไป', 'บทเรียนเขียนเสร็จแต่รอตรวจ 10 บท การเริ่มอีก 10 บทอาจเพิ่มคิว ควรช่วยลดคอขวดการตรวจก่อน', 'เสนอวิธีจัดการเมื่องาน 5 ชิ้นรอคนตรวจคนเดียว', 'ทำเกณฑ์ตรวจให้ชัด จัดลำดับงานที่ปลดเส้นทางหลัก และแบ่งผู้ตรวจที่เหมาะสมหากทำได้ หยุดเริ่มงานเพิ่มชั่วคราวเมื่อเพิ่มแต่คิวค้าง'),
    ('Agile Project Management', 'Lesson 7', 'Sub-lesson 1', 7, 1, 'Review and Retrospective', 'แยกการตรวจผลงานออกจากการปรับวิธีทำงานได้', 'Review ตรวจผลที่ส่งมอบและเรียนรู้จากผู้เกี่ยวข้อง ส่วน retrospective มองวิธีทำงานของทีม ทั้งสองอย่างควรนำไปสู่การตัดสินใจหรือการทดลองปรับที่ชัดเจน', 'ในการ review ให้ลองของที่ใช้งานได้และเก็บข้อเสนอแนะ ใน retrospective ใช้เหตุการณ์จริง เลือกการปรับจำนวนน้อย และระบุเจ้าของพร้อมรอบติดตาม', 'Review พบว่าผู้เรียนหาแนวคำตอบไม่เจอ ส่วน retrospective พบว่าทีมไม่ได้ทดลองหน้าจอบนมือถือก่อนส่ง เป็นข้อมูลคนละด้าน', 'แยกสองประเด็น: ปุ่มเล็กเกินไป และงานตรวจเริ่มวันสุดท้าย พร้อมขั้นตอนถัดไป', 'ปุ่มเล็กเป็นข้อเสนอแนะต่อผลงาน ควรปรับและทดสอบ งานตรวจช้าเป็นกระบวนการ ควรทดลองตรวจเป็นช่วงระหว่างรอบและติดตามผล'),
    ('Agile Project Management', 'Lesson 8', 'Sub-lesson 1', 8, 1, 'Quality and Release Readiness', 'กำหนดความพร้อมที่ตรวจได้ก่อนส่งมอบ', 'คำว่าเสร็จต้องรวมคุณภาพที่จำเป็นต่อการใช้จริง ไม่ใช่เพียงเขียนโค้ดหรือเนื้อหาเสร็จ ควรมีเกณฑ์ร่วมเรื่องความถูกต้อง การเข้าถึง ข้อผิดพลาด และสิ่งที่ยังไม่รองรับ', 'ตรวจเส้นทางหลักและกรณีล้มเหลวด้วยข้อมูลเหมาะสม บันทึกข้อจำกัด เตรียมวิธีติดตามหลังส่ง และตัดสินใจจากความเสี่ยงที่ทราบ ไม่เลื่อนปัญหาที่ขัดขวางงานหลักไปโดยไม่มีแผน', 'คอร์สพร้อมทดลองเมื่อแต่ละบทเปิดได้ เนื้อหาตรงชื่อ ปุ่มจบบันทึกได้ และเมื่อบันทึกล้มเหลวผู้ใช้ยังลองใหม่ได้', 'เขียนเกณฑ์พร้อมทดลองสำหรับคอร์สจำลอง 4 ข้อ', 'เนื้อหาครบตามบทและระบุว่าเป็นตัวอย่าง; อ่านบนมือถือได้; ผู้มีสิทธิ์เข้าถึงและบันทึกความคืบหน้าได้; กรณีไม่มีเนื้อหาหรือ API ล้มเหลวมีข้อความชัดเจน'),
    ('Design Thinking Fundamentals', 'Lesson 1', 'Sub-lesson 1', 1, 1, 'Understanding Design Thinking', 'แยกปัญหา สมมติฐาน และวิธีแก้ได้', 'Design thinking เป็นแนวทางเรียนรู้ปัญหาของคนและทดลองวิธีแก้ ไม่ใช่ลำดับขั้นที่ทำครั้งเดียวแล้วจบ ทีมอาจกลับไปหาข้อมูลใหม่เมื่อพบว่าสมมติฐานเดิมไม่ตรงกับสิ่งที่สังเกต', 'เริ่มจากเขียนสิ่งที่รู้พร้อมหลักฐาน แยกสิ่งที่ยังเดา แล้วเลือกข้อสงสัยที่สำคัญที่สุดไปตรวจสอบ การถามปัญหาให้ชัดช่วยลดการสร้างสิ่งที่ไม่มีใครต้องการ', 'คนไม่ใช้ห้องสมุดอาจเพราะเวลาเปิดไม่ตรงกับเวลาว่าง การสร้างแอปจองที่นั่งยังไม่ช่วยหากข้อจำกัดอยู่ที่เวลา', 'แยกประโยคห้องสมุดต้องมีแอปใหม่เป็นปัญหา สมมติฐาน และข้อเสนอ', 'ข้อเสนอคือแอปใหม่ สมมติฐานคือแอปช่วยเพิ่มการใช้งาน ส่วนปัญหายังต้องระบุจากหลักฐาน เช่น นักศึกษาเข้าถึงที่นั่งไม่ได้ในเวลาที่ต้องการ'),
    ('Design Thinking Fundamentals', 'Lesson 2', 'Sub-lesson 1', 2, 1, 'Empathy and Observation', 'สังเกตบริบทโดยไม่ด่วนสรุปเจตนาได้', 'การเข้าใจผู้ใช้ต้องดูทั้งสิ่งที่ทำและบริบทที่ทำ พฤติกรรมเดียวกันอาจมีหลายสาเหตุ การสังเกตจึงควรบันทึกเหตุการณ์ก่อนตีความ', 'เลือกกิจกรรมหนึ่ง ขอความยินยอมก่อนสังเกต จดลำดับและจุดสะดุด แล้วถามเหตุผลอย่างเป็นกลาง หลีกเลี่ยงบันทึกข้อมูลส่วนตัวที่ไม่จำเป็น', 'ผู้ใช้หยุดหน้าชำระเงินอาจกำลังหาบัตร ไม่ได้แปลว่าไม่เข้าใจหน้าจอเสมอไป', 'เขียนสิ่งที่สังเกตและคำถามติดตามจากผู้ใช้ที่ย้อนกลับไปดูราคา 3 ครั้ง', 'สิ่งที่เห็นคือกลับไปดูราคา 3 ครั้ง คำถามคือขณะนั้นกำลังตรวจข้อมูลอะไร อย่าเขียนทันทีว่าราคาแพงจนผู้ใช้ไม่พอใจ'),
    ('Design Thinking Fundamentals', 'Lesson 3', 'Sub-lesson 1', 3, 1, 'Defining the Problem', 'เขียนโจทย์โดยเชื่อมผู้ใช้ ความต้องการ และเหตุผลได้', 'โจทย์ที่ดีมีผู้ใช้ชัดเจน ระบุความต้องการ และบอกเหตุผลจากข้อมูล หากโจทย์กว้างเกินไปทีมจะไม่รู้ว่าจะตรวจผลอย่างไร หากแคบเป็นฟีเจอร์จะปิดโอกาสทางเลือก', 'รวมข้อสังเกตที่คล้ายกันแล้วเขียนประโยคผู้ใช้กลุ่มใดต้องการทำอะไรเพราะอะไร ตรวจทุกส่วนว่ามีหลักฐานหรือเป็นข้อสันนิษฐาน', 'นักศึกษาที่ทำงานตอนเย็นต้องการพื้นที่อ่านหนังสือช่วงดึก เพราะเวลาห้องสมุดปัจจุบันทับกับเวลาทำงาน เป็นโจทย์ชัดกว่าสร้างแอปห้องสมุด', 'เขียนโจทย์สำหรับผู้เรียนที่เปิดคอร์สแล้วไม่รู้ว่าควรเริ่มบทไหน', 'ผู้เรียนใหม่ต้องการเห็นจุดเริ่มและลำดับบท เพราะยังไม่รู้พื้นฐานที่แต่ละบทต้องใช้ จากนั้นตรวจว่าปัญหาเกิดกับผู้เรียนกลุ่มใดจริง'),
    ('Design Thinking Fundamentals', 'Lesson 4', 'Sub-lesson 1', 4, 1, 'Generating Ideas', 'สร้างทางเลือกหลายแบบก่อนเลือกคำตอบได้', 'ช่วงสร้างไอเดียมีเป้าหมายขยายทางเลือก จึงควรแยกจากช่วงประเมิน การเลือกไอเดียแรกทันทีทำให้ทีมมองข้ามวิธีแก้ที่ใช้กระบวนการหรือการสื่อสารแทนเทคโนโลยี', 'กำหนดโจทย์เดียว ให้แต่ละคนเขียนเงียบ ๆ ก่อนแบ่งปัน รวมแนวคิดที่เกี่ยวข้อง แล้วใช้เกณฑ์ที่ตกลงร่วมกันเลือกสิ่งที่จะทดลอง', 'ปัญหาไม่รู้บทเริ่มต้นอาจแก้ด้วยแผนการเรียน แบบประเมินพื้นฐาน หรือคำแนะนำจากผู้สอน ไม่จำเป็นต้องเริ่มจากระบบแนะนำอัตโนมัติ', 'เสนอสามแนวทางลดความสับสนเมื่อเริ่มคอร์ส โดยอย่างน้อยหนึ่งแนวทางไม่ต้องเขียนระบบใหม่', 'คู่มือเริ่มต้นหนึ่งหน้า, ป้ายกำกับบทพื้นฐาน, และแบบประเมินก่อนเรียน เปรียบเทียบความเข้าใจของผู้ใช้และแรงที่ใช้ดูแลแต่ละแนวทาง'),
    ('Design Thinking Fundamentals', 'Lesson 5', 'Sub-lesson 1', 5, 1, 'Choosing Experiments', 'เลือกสมมติฐานเสี่ยงเพื่อทดสอบก่อนลงทุนได้', 'ไอเดียหนึ่งมีสมมติฐานหลายข้อ ทั้งผู้ใช้ต้องการหรือไม่ ทำได้หรือไม่ และดูแลได้หรือไม่ ควรทดสอบข้อที่หากผิดจะทำให้แนวคิดไปต่อไม่ได้ก่อน', 'เขียนสมมติฐานเป็นประโยคที่ตรวจได้ กำหนดหลักฐานที่จะใช้และเกณฑ์ตัดสินก่อนทดลอง ไม่เปลี่ยนเกณฑ์ย้อนหลังเพื่อให้ผลดูดี', 'ก่อนทำระบบจับคู่เพื่อนเรียน ทดลองจับคู่ด้วยคนกับกลุ่มเล็กเพื่อดูว่าผู้เรียนมาพบกันตามนัดหรือไม่', 'กำหนดสมมติฐานและผลสังเกตสำหรับแผนเรียนรายสัปดาห์', 'สมมติฐานคือผู้เรียนวางเวลาเรียนได้เมื่อเห็นงานรายสัปดาห์ สังเกตว่าเขาจัดแผนได้โดยไม่ต้องให้ผู้ทดสอบช่วย และติดตามว่าทำตามแผนได้อย่างไร'),
    ('Design Thinking Fundamentals', 'Lesson 6', 'Sub-lesson 1', 6, 1, 'Building Low-Cost Prototypes', 'ลดขอบเขตต้นแบบให้ตอบคำถามเดียวได้', 'ต้นแบบราคาต่ำทำให้เปลี่ยนแนวทางได้เร็ว ความละเอียดควรพอให้ผู้ใช้เข้าใจสถานการณ์ แต่ไม่ต้องทำทุกส่วนเหมือนผลิตภัณฑ์จริง', 'เลือกเส้นทางหลักหนึ่งเส้น วาดเฉพาะข้อมูลและปุ่มที่จำเป็น เตรียมผลตอบสนองเมื่อกด และบอกข้อจำกัดของต้นแบบโดยไม่ชี้นำคำตอบ', 'ใช้กระดาษสามหน้าแทนหน้ารายการบท หน้าบทเรียน และหน้าสรุป เพื่อทดสอบว่าผู้ใช้หาบทถัดไปได้หรือไม่', 'กำหนดสิ่งที่ต้องมีและสิ่งที่ยังไม่ต้องมีในต้นแบบเลือกบทเรียน', 'ต้องมีชื่อบท ลำดับ และปุ่มไปต่อ ยังไม่ต้องมีระบบชำระเงินหรือวิดีโอจริง หากคำถามคือผู้ใช้เข้าใจลำดับการเรียนหรือไม่'),
    ('Design Thinking Fundamentals', 'Lesson 7', 'Sub-lesson 1', 7, 1, 'Testing and Iteration', 'ใช้ผลทดลองปรับแนวคิดโดยไม่เลือกเฉพาะคำชมได้', 'ผลทดสอบมีทั้งพฤติกรรมที่เห็นและความคิดเห็น คำชมไม่ได้หมายความว่างานสำเร็จเสมอไป จึงต้องตรวจว่าผู้ใช้ทำสิ่งที่ตั้งใจได้จริงหรือไม่', 'สรุปสิ่งที่คาด สิ่งที่เกิด และสิ่งที่จะเปลี่ยน แก้ปัญหาที่ขัดขวางงานหลักก่อน แล้วทดสอบอีกครั้งด้วยโจทย์เทียบเคียงเดิม', 'ผู้ใช้บอกว่าหน้าสวยแต่หาเริ่มเรียนไม่พบ ทีมควรแก้ลำดับข้อมูลและปุ่มก่อนเพิ่มภาพตกแต่ง', 'จากผลผู้ใช้ 3 คนหาเริ่มเรียนไม่พบ แต่ชอบสี ให้เลือกการแก้และวิธีตรวจต่อ', 'ทำปุ่มเริ่มเรียนชัดขึ้นในบริบทของบทแรก แล้วทดสอบว่าผู้ใช้ใหม่เริ่มงานได้โดยไม่ช่วย ไม่ใช้จำนวนคำชมสีเป็นตัวชี้วัดการแก้ปัญหานี้'),
    ('Design Thinking Fundamentals', 'Lesson 8', 'Sub-lesson 1', 8, 1, 'Presenting a Design Story', 'สื่อสารเหตุผลของแนวทางออกแบบจากหลักฐานได้', 'การเล่าเรื่องงานออกแบบควรเชื่อมบริบท ปัญหา หลักฐาน แนวทาง และผลทดลอง ผู้ฟังต้องเห็นว่าการตัดสินใจเกิดจากอะไรและยังไม่รู้อะไร', 'เลือกหลักฐานสำคัญเพียงพอให้ตรวจสอบได้ แสดงสิ่งที่เปลี่ยนหลังทดสอบ และจบด้วยคำถามหรือขั้นตอนถัดไปที่ชัด หลีกเลี่ยงอ้างว่ากลุ่มเล็กเป็นตัวแทนผู้ใช้ทั้งหมด', 'ทีมแสดงจุดที่ผู้ใช้ติดในต้นแบบแรก จากนั้นแสดงหน้าที่ปรับและพฤติกรรมในการทดสอบครั้งถัดไป พร้อมระบุขนาดกลุ่ม', 'ร่างการนำเสนอ 5 ส่วนสำหรับโครงการช่วยผู้เรียนเริ่มบทแรก', 'บริบทผู้เรียน → ปัญหาที่สังเกต → แนวทางที่ทดลอง → ผลและข้อจำกัด → ขั้นตอนถัดไป ควรเชื่อมทุกข้อเสนอเข้ากับข้อมูลแทนการแสดงหน้าจออย่างเดียว'),
    ('UX Research Methods', 'Lesson 1', 'Sub-lesson 1', 1, 1, 'Research Questions and Planning', 'เลือกคำถามวิจัยที่ช่วยตัดสินใจได้', 'คำถามวิจัยระบุสิ่งที่ทีมต้องเรียนรู้ ส่วนคำถามสัมภาษณ์คือสิ่งที่ถามผู้เข้าร่วม ทั้งสองอย่างไม่จำเป็นต้องใช้ถ้อยคำเหมือนกัน แผนที่ดีเริ่มจากการตัดสินใจที่จะใช้ผล', 'ระบุความไม่แน่นอน กลุ่มผู้ใช้ วิธีเก็บข้อมูล และผลที่จะส่งมอบ เลือกวิธีให้ตรงคำถาม เช่น สัมภาษณ์เพื่อเข้าใจเหตุผลหรือสังเกตเพื่อดูการทำงาน', 'ทีมต้องตัดสินใจว่าจะปรับขั้นตอนสมัครตรงไหน คำถามวิจัยคือผู้ใช้ติดขัดช่วงใด คำถามสัมภาษณ์คือช่วยเล่าครั้งล่าสุดที่สมัครให้ฟัง', 'เขียนคำถามวิจัยและวิธีเก็บข้อมูลสำหรับผู้เรียนที่หยุดกลางคอร์ส', 'ถามว่าปัจจัยใดทำให้หยุดและในบริบทใด ใช้สัมภาษณ์ผู้ที่หยุดล่าสุดร่วมกับข้อมูลการเรียนที่ได้รับอนุญาต ไม่สรุปเหตุผลจากจำนวนคลิกอย่างเดียว'),
    ('UX Research Methods', 'Lesson 2', 'Sub-lesson 1', 2, 1, 'Recruiting Participants', 'เลือกผู้เข้าร่วมตามพฤติกรรมที่เกี่ยวข้องได้', 'ผู้เข้าร่วมควรมีประสบการณ์ตรงกับคำถาม การเลือกเฉพาะคนใกล้ตัวอาจทำให้มุมมองแคบ แต่การเลือกกลุ่มหลากหลายโดยไม่เกี่ยวกับโจทย์ก็ไม่ช่วยตอบคำถาม', 'เขียนเกณฑ์รับและไม่รับอย่างมีเหตุผล ใช้คำถามคัดกรองพฤติกรรม แจ้งวัตถุประสงค์และการใช้ข้อมูล พร้อมเปิดให้ปฏิเสธหรือยุติการเข้าร่วมได้', 'ศึกษาการซื้อคอร์สครั้งแรกควรมีคนที่เพิ่งซื้อครั้งแรก ไม่ใช่เลือกเฉพาะผู้เรียนประจำที่คุ้นหน้าจอแล้ว', 'ร่างเกณฑ์คัดเลือกสองข้อสำหรับศึกษาการค้นหาคอร์สบนมือถือ', 'เคยค้นหาคอร์สบนมือถือในช่วงที่กำหนด และมีเป้าหมายเรียนที่อธิบายได้ ควรครอบคลุมทั้งคนที่ซื้อและไม่ซื้อเพื่อไม่มองเฉพาะเส้นทางสำเร็จ'),
    ('UX Research Methods', 'Lesson 3', 'Sub-lesson 1', 3, 1, 'Interview Techniques', 'ถามต่อเพื่อได้รายละเอียดโดยไม่ชี้นำได้', 'สัมภาษณ์เชิงลึกใช้คำถามเปิดและคำถามติดตามเพื่อเข้าใจประสบการณ์ คำถามที่ใส่เหตุผลไว้ล่วงหน้าทำให้ผู้เข้าร่วมตอบตามกรอบของผู้วิจัย', 'เริ่มจากเหตุการณ์ล่าสุด ถามว่าเกิดอะไรต่อและตัดสินใจอย่างไร เว้นจังหวะให้คิด แล้วทวนความเข้าใจเพื่อให้แก้ไขได้ หลีกเลี่ยงถามหลายเรื่องในประโยคเดียว', 'แทนถามว่าหยุดเรียนเพราะบทเรียนยาวใช่ไหม ให้ถามว่าตอนตัดสินใจหยุดเกิดอะไรขึ้น และขณะนั้นพยายามทำอะไร', 'แก้คำถามปุ่มนี้หาไม่เจอเพราะสีอ่อนไปใช่ไหมให้เป็นกลาง', 'ถามว่าตอนนั้นกำลังมองหาอะไรและมองตรงไหนบ้าง จากนั้นจึงถามถึงสิ่งที่ช่วยหรือขัดขวางการมองเห็นโดยไม่ระบุสาเหตุแทนผู้ใช้'),
    ('UX Research Methods', 'Lesson 4', 'Sub-lesson 1', 4, 1, 'Contextual Observation', 'แยกบันทึกเหตุการณ์ออกจากข้อสันนิษฐานได้', 'การสังเกตในบริบทช่วยเห็นเครื่องมือ ข้อจำกัด และวิธีแก้ปัญหาเฉพาะหน้าที่ผู้ใช้อาจไม่ได้เล่า สภาพแวดล้อมและการขัดจังหวะอาจมีผลต่อพฤติกรรมมากกว่าหน้าจอ', 'บันทึกเวลา การกระทำ และคำพูดในช่องหลักฐาน แยกช่องตีความไว้ต่างหาก ถามยืนยันหลังช่วงงานที่เหมาะสมเพื่อไม่รบกวนกิจกรรมมากเกินไป', 'ผู้เรียนหยุดวิดีโอทุกสองนาทีเพราะจดลงสมุด อาจเป็นวิธีเรียนที่ตั้งใจ ไม่ใช่สัญญาณว่าเบื่อ', 'เขียนบันทึกสองช่องจากเหตุการณ์ผู้ใช้สลับแอปธนาคารก่อนกลับมาชำระเงิน', 'หลักฐาน: สลับไปแอปธนาคารแล้วกลับมา ข้อสันนิษฐาน: ตรวจยอดหรือทำธุรกรรม ต้องถามยืนยัน ไม่บันทึกว่าชำระล้มเหลวหากยังไม่เห็นผล'),
    ('UX Research Methods', 'Lesson 5', 'Sub-lesson 1', 5, 1, 'Survey Design', 'เขียนคำถามแบบสอบถามที่ตีความได้ชัดเจน', 'แบบสอบถามช่วยเก็บคำตอบในรูปแบบเดียวกัน แต่คุณภาพขึ้นกับคำถามและวิธีเลือกผู้ตอบ คำถามสองประเด็นในข้อเดียวทำให้ไม่รู้ว่าคะแนนสะท้อนเรื่องใด', 'ใช้ช่วงเวลาและคำที่ชัด แยกแต่ละประเด็น ทำตัวเลือกที่ครอบคลุมและไม่ทับกัน และทดลองกับคนกลุ่มเล็กก่อนส่งจริง รายงานข้อจำกัดของกลุ่มที่ตอบด้วย', 'แทนถามว่าบทเรียนสนุกและเข้าใจง่ายไหม ให้แยกความน่าสนใจกับความเข้าใจเป็นคนละข้อ', 'ปรับคำถามคุณเรียนบ่อยแค่ไหนให้ตอบและตีความได้ตรงกัน', 'ใน 7 วันที่ผ่านมา คุณเปิดเรียนกี่วัน: 0, 1–2, 3–4, 5–7 วัน ช่วงไม่ทับกันและระบุหน่วยชัด แต่ควรตรวจว่าต้องการวัดเปิดเรียนหรือเรียนจบ'),
    ('UX Research Methods', 'Lesson 6', 'Sub-lesson 1', 6, 1, 'Synthesis and Themes', 'สรุปประเด็นโดยรักษาความเชื่อมโยงกับหลักฐานได้', 'การสังเคราะห์เปลี่ยนข้อมูลกระจัดกระจายเป็นรูปแบบที่ช่วยตัดสินใจ ธีมควรอธิบายสิ่งที่ข้อมูลมีร่วมกัน ไม่ใช่แค่หมวดกว้าง ๆ เช่น ปัญหาผู้ใช้', 'แยกข้อสังเกตเป็นรายการ จัดกลุ่มตามความหมาย ตั้งชื่อธีม และแนบหลักฐานย้อนกลับ ตรวจกรณีที่ไม่เข้ากลุ่มด้วยเพื่อไม่กลบความแตกต่าง', 'คำพูดไม่รู้ว่าจ่ายแล้วหรือยังและรออีเมลอยู่นานอาจรวมเป็นธีมขาดการยืนยันหลังชำระเงิน แต่ต้องตรวจว่าเป็นเหตุการณ์เดียวกันหรือคนละปัญหา', 'สร้างธีมจากผู้ใช้สามคนที่ค้นหาปุ่มเริ่มเรียน ถามว่าต้องเรียนตามลำดับไหม และไม่รู้พื้นฐานที่ต้องมี', 'ธีมอาจเป็นไม่เห็นเส้นทางเริ่มต้น โดยแยกหลักฐานด้านปุ่ม ลำดับ และพื้นฐานไว้ อย่ารวมจนมองไม่เห็นว่าต้องแก้คนละส่วน'),
    ('UX Research Methods', 'Lesson 7', 'Sub-lesson 1', 7, 1, 'Research Reporting', 'รายงานข้อค้นพบพร้อมความมั่นใจและข้อจำกัดได้', 'รายงานวิจัยควรแยกสิ่งที่พบ การตีความ และข้อเสนอ ผลจากกลุ่มเล็กช่วยชี้ปัญหาได้ แต่ไม่ควรแปลงเป็นสัดส่วนของผู้ใช้ทั้งหมดโดยไม่มีวิธีสุ่มที่รองรับ', 'เริ่มจากคำถามและกลุ่มที่ศึกษา สรุปประเด็นสำคัญพร้อมหลักฐาน ระบุข้อจำกัด และเสนอการตัดสินใจหรือการศึกษาต่อที่ผลรองรับ', 'รายงานว่าผู้เข้าร่วม 4 จาก 5 คนในรอบนี้หาใบเสร็จไม่พบ มีความหมายต่างจากอ้างว่า 80% ของลูกค้าทั้งหมดหาไม่พบ', 'ร่างข้อค้นพบหนึ่งข้อจากการทดสอบ 5 คน โดย 3 คนไม่ทราบว่ากดสมัครสำเร็จแล้ว', 'ในรอบนี้ 3 จาก 5 คนไม่พบการยืนยันหลังสมัคร แนบพฤติกรรมหรือคำพูด เสนอปรับสถานะยืนยัน และระบุว่ายังไม่ทราบความถี่ของปัญหาในผู้ใช้ทั้งหมด'),
    ('Product Strategy', 'Lesson 1', 'Sub-lesson 1', 1, 1, 'Product Vision', 'เขียนทิศทางผลิตภัณฑ์ที่เชื่อมกับปัญหาผู้ใช้ได้', 'วิสัยทัศน์ผลิตภัณฑ์อธิบายอนาคตที่อยากสร้างให้ใครและทำไม ไม่ใช่รายการฟีเจอร์ทั้งหมด ทิศทางที่ชัดช่วยตัดสินใจว่างานใดสนับสนุนเป้าหมายและงานใดควรพักไว้', 'ระบุกลุ่มเป้าหมาย ปัญหาหลัก และผลลัพธ์ระยะยาว จากนั้นลองใช้ประโยคนี้เลือกหรือปฏิเสธงานตัวอย่าง หากใช้ตัดสินใจไม่ได้อาจยังกว้างเกินไป', 'ช่วยคนทำงานเริ่มทักษะใหม่ด้วยบทเรียนที่จบได้ในเวลาจำกัด ชี้ทิศทางชัดกว่าสร้างแพลตฟอร์มที่ดีที่สุด', 'เขียนวิสัยทัศน์สำหรับแอปฝึกเขียนโปรแกรมสำหรับผู้เริ่มต้น', 'ช่วยผู้เริ่มต้นสร้างโปรแกรมเล็กที่ใช้งานได้ด้วยการฝึกทีละขั้น ระบุผู้ใช้และผลลัพธ์ แล้วตรวจว่าข้อเสนอใหม่ช่วยให้ลงมือทำได้จริงหรือไม่'),
    ('Product Strategy', 'Lesson 2', 'Sub-lesson 1', 2, 1, 'Customer Segments', 'แบ่งกลุ่มตามความต้องการและบริบทได้', 'กลุ่มลูกค้าที่มีอายุเท่ากันอาจมีงานที่ต้องทำต่างกัน การแบ่งกลุ่มเพื่อวางกลยุทธ์ควรดูเป้าหมาย ข้อจำกัด และพฤติกรรมที่ส่งผลต่อการเลือกผลิตภัณฑ์', 'รวบรวมรูปแบบความต้องการ เลือกกลุ่มเริ่มต้นที่ทีมเข้าใจและเข้าถึงได้ เขียนสิ่งที่เลือกโฟกัสพร้อมเหตุผล และระบุสิ่งที่ยังไม่รองรับ', 'ผู้เรียนเพื่อเปลี่ยนอาชีพต้องการโครงงานและข้อเสนอแนะ ส่วนผู้เรียนเพื่อแก้งานเฉพาะหน้าต้องการค้นคำตอบได้เร็ว', 'แบ่งผู้เรียนออนไลน์สองกลุ่มตามเป้าหมาย และบอกความต้องการที่ต่างกัน', 'เปลี่ยนอาชีพ: ต้องการเส้นทางฝึกและผลงาน แก้งานปัจจุบัน: ต้องการบทสั้นค้นง่าย ควรตรวจการแบ่งนี้กับข้อมูลจริงก่อนกำหนดผลิตภัณฑ์'),
    ('Product Strategy', 'Lesson 3', 'Sub-lesson 1', 3, 1, 'Problem and Opportunity', 'ประเมินโอกาสโดยไม่สับสนกับขนาดของไอเดียได้', 'โอกาสผลิตภัณฑ์เกิดจากปัญหาที่มีความสำคัญและยังได้รับการแก้ไม่ดีพอ ต้องดูความถี่ ความรุนแรง ทางเลือกปัจจุบัน และข้อจำกัดของทีมร่วมกัน', 'เขียนคำอธิบายปัญหาพร้อมหลักฐาน ตรวจว่าผู้ใช้พยายามแก้อย่างไรและมีต้นทุนอะไร แล้วแยกสิ่งที่ทราบจากขนาดโอกาสที่ยังต้องประเมิน', 'ผู้เรียนส่งงานผ่านหลายช่องทางจนหาข้อเสนอแนะไม่พบ อาจเป็นโอกาสรวมประวัติงาน แต่ต้องตรวจว่าปัญหาเกิดบ่อยและกับใคร', 'ระบุข้อมูลสามอย่างที่ต้องหาเพิ่มก่อนทำระบบส่งการบ้านใหม่', 'ความถี่ของงานตกหล่น ผลกระทบต่อผู้เรียนและผู้สอน และวิธีแก้ปัจจุบัน รวมต้นทุนเปลี่ยนระบบด้วย ไม่ใช้เพียงจำนวนคนบอกว่าน่าสนใจ'),
    ('Product Strategy', 'Lesson 4', 'Sub-lesson 1', 4, 1, 'Value Proposition', 'อธิบายคุณค่าจากผลลัพธ์แทนรายการฟีเจอร์ได้', 'คุณค่าที่เสนอเชื่อมปัญหาของกลุ่มเป้าหมายกับผลที่ผลิตภัณฑ์ช่วยให้เกิด ฟีเจอร์เป็นวิธีส่งมอบคุณค่า แต่การมีฟีเจอร์มากไม่ได้แปลว่าช่วยผู้ใช้ได้มาก', 'เขียนสำหรับใคร มีปัญหาอะไร ช่วยอย่างไร และแตกต่างจากทางเลือกใด ตรวจคำกล่าวอ้างด้วยหลักฐานหรือกำหนดเป็นสมมติฐานที่จะทดลอง', 'รวมคำแนะนำของผู้สอนไว้ที่งานแต่ละชิ้นเพื่อให้แก้รอบต่อไปง่ายขึ้น สื่อผลลัพธ์ชัดกว่ามี dashboard ใหม่', 'เปลี่ยนข้อความมีวิดีโอ 100 คลิปให้เป็นคุณค่าที่ต้องทดสอบ', 'ช่วยผู้เริ่มต้นฝึกจนสร้างหน้าเว็บแรกได้ด้วยบทเรียนเรียงลำดับ ต้องทดสอบว่าผู้เรียนทำสำเร็จจริง ไม่ใช้จำนวนคลิปเป็นหลักฐานของผลลัพธ์'),
    ('Product Strategy', 'Lesson 5', 'Sub-lesson 1', 5, 1, 'Positioning and Alternatives', 'เปรียบเทียบกับทางเลือกที่ลูกค้าใช้จริงได้', 'คู่เปรียบเทียบไม่ได้มีเฉพาะผลิตภัณฑ์ประเภทเดียวกัน ผู้ใช้อาจใช้สเปรดชีต ถามเพื่อน หรือไม่ทำอะไรเลย การวางตำแหน่งต้องอธิบายว่าทำไมจึงคุ้มค่าที่จะเปลี่ยน', 'เลือกเกณฑ์จากงานของผู้ใช้ เปรียบเทียบทางเลือกด้วยหลักฐาน และระบุข้อแลกเปลี่ยนของผลิตภัณฑ์ตนเอง หลีกเลี่ยงตารางที่เลือกแต่เกณฑ์ซึ่งทำให้ตนเองชนะ', 'คอร์สมีผู้ให้ข้อเสนอแนะอาจเหมาะกับคนที่ต้องการแก้งาน แต่บทความฟรีอาจเหมาะกับคนที่ต้องการคำตอบสั้นทันที', 'เปรียบเทียบคอร์สออนไลน์กับการอ่านบทความในสองเกณฑ์', 'โครงสร้างการเรียนและการได้รับข้อเสนอแนะเป็นสองเกณฑ์ที่เป็นไปได้ ระบุว่าบทความบางชุดมีโครงสร้างและคอร์สบางแห่งไม่มีผู้ตรวจงาน ต้องดูของจริงก่อนสรุป'),
    ('Product Strategy', 'Lesson 6', 'Sub-lesson 1', 6, 1, 'Outcomes and Metrics', 'แยกผลลัพธ์ผู้ใช้ออกจากจำนวนงานที่ส่งได้', 'Output คือสิ่งที่ทีมส่งมอบ เช่น จำนวนบทเรียน ส่วน outcome คือการเปลี่ยนแปลงที่ต้องการ เช่น ผู้เรียนทำโจทย์ได้ด้วยตนเอง ตัวเลขการใช้งานต้องตีความในบริบทของเป้าหมาย', 'กำหนดผลลัพธ์หนึ่งอย่าง ตัวชี้วัด วิธีนับ และช่วงเวลา เพิ่มตัวชี้วัดเฝ้าระวังผลข้างเคียง เช่น ความพึงพอใจหรือการขอคืนเงิน', 'เพิ่มบทเรียน 10 บทเป็น output สัดส่วนผู้เรียนที่ทำโครงงานผ่านเกณฑ์เป็นตัวชี้วัด outcome แต่ต้องกำหนดเกณฑ์และกลุ่มผู้เรียนชัดเจน', 'เลือกตัวชี้วัดหลักและตัวเฝ้าระวังสำหรับการย่อบทเรียนให้สั้นลง', 'หลัก: สัดส่วนผู้เรียนทำโจทย์หลังบทได้ เฝ้าระวัง: ความสับสนหรือการขอความช่วยเหลือ ไม่ใช้เวลาชมที่ลดลงเป็นความสำเร็จเพียงตัวเดียว'),
    ('Product Strategy', 'Lesson 7', 'Sub-lesson 1', 7, 1, 'Prioritization', 'เปรียบเทียบงานด้วยเหตุผลและความไม่แน่นอนได้', 'การจัดลำดับคือการเลือกใช้ทรัพยากรจำกัด งานที่น่าสนใจอาจไม่ใช่งานที่สำคัญที่สุด คะแนนช่วยให้คุยเป็นระบบแต่ขึ้นกับคุณภาพของค่าที่ประเมิน', 'ใช้เกณฑ์ผลกระทบ ความมั่นใจ และแรงที่ต้องใช้ ระบุที่มาของค่าประเมิน ตรวจงานที่เป็นข้อจำกัดหรือสิ่งจำเป็นก่อนเปรียบเทียบคะแนน', 'แก้ปัญหาเปิดบทเรียนไม่ได้อาจสำคัญกว่าธีมสีใหม่ เพราะเป็นข้อขัดขวางงานหลัก แม้ทำให้ดูใหม่ได้น้อยกว่า', 'จัดลำดับแก้วิดีโอไม่เล่น เพิ่มธีมสี และปรับค้นหาบท พร้อมเหตุผล', 'เริ่มแก้วิดีโอหากกระทบการเรียนจริง แล้วประเมินค้นหาตามจำนวนผู้ติดขัด ธีมสีอาจตามหลังเมื่อไม่มีหลักฐานว่าขัดขวางงาน ระบุข้อมูลที่จะทำให้เปลี่ยนลำดับด้วย'),
    ('Product Strategy', 'Lesson 8', 'Sub-lesson 1', 8, 1, 'Roadmaps and Dependencies', 'สื่อสารแผนโดยแยกเป้าหมายออกจากความแน่นอนของวันได้', 'Roadmap เชื่อมเป้าหมายกับงานที่คาดว่าจะช่วยให้ถึงเป้าหมาย งานระยะไกลมักไม่แน่นอนเท่างานใกล้ การแสดงทุกอย่างเป็นคำมั่นวันส่งอาจทำให้สื่อสารเกินหลักฐาน', 'จัดช่วงปัจจุบัน ถัดไป และภายหลัง ระบุผลลัพธ์และสิ่งที่ต้องเรียนรู้ รวมงานที่พึ่งพากัน เช่น ต้องมีเนื้อหาก่อนทดสอบเส้นทางเรียน', 'ปัจจุบันทำให้อ่านบทได้ ถัดไปทดลองแบบฝึกหัด ภายหลังประเมินการให้ข้อเสนอแนะอัตโนมัติ แต่ละช่วงมีเกณฑ์ตัดสินว่าจะไปต่อหรือไม่', 'วางแผนสามช่วงสำหรับเปิดคอร์สใหม่พร้อม dependency สำคัญ', 'เตรียมหลักสูตรและเนื้อหา → ทดสอบเรียนกับกลุ่มเล็ก → เปิดรับกลุ่มกว้าง ต้องตรวจเนื้อหาและเส้นทางเข้าถึงก่อนทดลองผลการเรียน'),
    ('Product Strategy', 'Lesson 9', 'Sub-lesson 1', 9, 1, 'Strategy Review', 'ทบทวนกลยุทธ์เมื่อหลักฐานเปลี่ยนได้', 'กลยุทธ์ประกอบด้วยทางเลือกและสมมติฐานที่ต้องตรวจต่อ การทบทวนไม่ใช่เปลี่ยนทิศทุกครั้งที่ตัวเลขแกว่ง แต่ดูว่าหลักฐานสะสมยังรองรับทางเลือกเดิมหรือไม่', 'กำหนดรอบทบทวน เปรียบเทียบผลกับเป้าหมาย ตรวจปัจจัยอื่น และบันทึกว่าจะทำต่อ ปรับ หรือหยุด พร้อมเหตุผลและสิ่งที่จะตรวจในรอบถัดไป', 'ผู้เรียนสมัครมากแต่ไม่เริ่มเรียน ทีมควรตรวจแรงจูงใจและขั้นตอนเริ่มก่อนเพิ่มงบหาผู้สมัคร โดยไม่สรุปว่าหลักสูตรไม่ดีทันที', 'เขียนบันทึกทบทวนเมื่อผู้สมัครเพิ่มแต่ผู้ทำโครงงานสำเร็จเท่าเดิม', 'แยกอัตราจากจำนวนจริง ตรวจรุ่นผู้เรียนและเวลาที่มีให้เรียน ตั้งสมมติฐานเรื่องการเริ่มหรือเนื้อหา แล้วเลือกตรวจหลักฐานก่อนตัดสินใจขยายการตลาด'),
    ('Service Design Essentials', 'Lesson 1', 'Welcome to the Course', 1, 1, 'Introduction to Service Design', 'แยกบริการออกจากจุดสัมผัสเพียงจุดเดียวได้', 'บริการคือชุดกิจกรรมที่ช่วยให้ผู้ใช้บรรลุเป้าหมาย ตั้งแต่ก่อนเริ่มใช้ ระหว่างใช้ ไปจนถึงหลังใช้ จุดสัมผัสคือสิ่งที่ผู้ใช้พบ เช่น แอป พนักงาน หรือใบเสร็จ การออกแบบบริการจึงต้องมองความสัมพันธ์ระหว่างจุดเหล่านี้ด้วย', 'เริ่มจากระบุผู้ใช้หนึ่งกลุ่มและเป้าหมายหนึ่งอย่าง แล้วไล่ลำดับว่าเขาต้องทำอะไรบ้าง จดทั้งสิ่งที่ผู้ใช้เห็นและงานเบื้องหลัง อย่าเริ่มด้วยการเลือกหน้าจอที่จะสร้าง เพราะปัญหาอาจอยู่ที่กระบวนการทำงาน', 'ร้านกาแฟรับคำสั่งซื้อผ่านแอปได้รวดเร็ว แต่ไม่มีป้ายจุดรับสินค้า ลูกค้ายังคงสับสน แม้หน้าจอสั่งซื้อจะใช้ง่ายก็ตาม', 'เลือกบริการใกล้ตัวหนึ่งอย่าง ระบุเป้าหมายผู้ใช้และจุดสัมผัสก่อน ระหว่าง และหลังใช้บริการ', 'ตัวอย่างร้านกาแฟ: เป้าหมายคือรับกาแฟทันก่อนทำงาน ก่อนใช้ดูเมนู ระหว่างใช้สั่งและจ่ายเงิน หลังใช้รับเครื่องดื่มและแจ้งปัญหา ควรครอบคลุมมากกว่าหน้าจอแอป'),
    ('Service Design Essentials', 'Lesson 2', 'Sub-lesson 1', 2, 1, 'Service Design Principles', 'ใช้มุมมองผู้ใช้และการทำงานร่วมกันปรับบริการได้', 'หลักคิดสำคัญคือเริ่มจากผู้ใช้ มองบริการทั้งระบบ และให้คนที่เกี่ยวข้องร่วมออกแบบ ความสะดวกของลูกค้าต้องสอดคล้องกับความสามารถของพนักงานและระบบ มิฉะนั้นแนวคิดที่ดีอาจทำงานจริงไม่ได้', 'รวบรวมปัญหาจากลูกค้าและทีมปฏิบัติการ แล้วเขียนหลักการตัดสินใจที่สังเกตได้ เช่น ลูกค้าต้องทราบขั้นตอนถัดไปเสมอ ใช้หลักการนี้เปรียบเทียบแนวทางแก้ ไม่ใช้ความชอบส่วนตัวเป็นเกณฑ์เดียว', 'โรงแรมเพิ่มข้อความบอกเวลาห้องพร้อมและผู้ติดต่อ ทำให้ลูกค้ารู้ว่าจะทำอะไรต่อ ขณะเดียวกันพนักงานต้องมีวิธีอัปเดตเวลาที่ทำได้จริง', 'เขียนหลักการออกแบบสองข้อสำหรับบริการนัดหมาย พร้อมวิธีสังเกตว่าเป็นไปตามหลักการหรือไม่', 'เช่น รู้สถานะเสมอ: ผู้ใช้เห็นวัน เวลา และสถานที่นัดชัดเจน แก้ไขได้ง่าย: ผู้ใช้เลื่อนนัดได้โดยไม่ต้องกรอกข้อมูลเดิมทั้งหมด แต่ต้องตรวจข้อจำกัดของผู้ให้บริการด้วย'),
    ('Service Design Essentials', 'Lesson 3', 'Sub-lesson 1', 3, 1, 'User Research and Journey Mapping', 'สร้างแผนที่ประสบการณ์จากข้อมูลผู้ใช้ได้', 'Journey map แสดงขั้นตอน การกระทำ ความรู้สึก และปัญหาของผู้ใช้ในสถานการณ์หนึ่ง แผนที่ที่มีประโยชน์อ้างอิงการสังเกตหรือคำบอกเล่าจากเหตุการณ์จริง ไม่เติมความรู้สึกแทนผู้ใช้โดยไม่มีหลักฐาน', 'ถามผู้ใช้ถึงครั้งล่าสุดที่ใช้บริการ แบ่งเหตุการณ์เป็นช่วง แล้วบันทึกคำพูดและปัญหาแยกจากข้อสันนิษฐาน เลือกจุดที่ติดขัดและระบุข้อมูลที่ยังต้องหาเพิ่มก่อนเสนอวิธีแก้', 'ผู้สมัครคอร์สค้นหา เปรียบเทียบ จ่ายเงิน แล้วรออีเมล จุดติดขัดอาจเป็นการไม่รู้ว่าชำระเงินสำเร็จหรือยัง ไม่ใช่การหาปุ่มจ่ายไม่พบ', 'ทำ journey map สี่ขั้นตอนของการสมัครคอร์ส และระบุปัญหาหนึ่งจุดที่ต้องสัมภาษณ์เพิ่ม', 'ค้นหา → เปรียบเทียบ → ชำระเงิน → เข้าเรียน จดหลักฐานแต่ละช่วง หากคาดว่าผู้ใช้กังวลหลังจ่ายเงิน ให้ถามว่าเขาตรวจสอบสถานะอย่างไรในครั้งล่าสุด'),
    ('Service Design Essentials', 'Lesson 4', 'Sub-lesson 1', 4, 1, 'Framing and Prioritizing Opportunities', 'เปลี่ยนปัญหาเป็นโจทย์ที่ทดสอบได้', 'โจทย์ออกแบบควรระบุว่าใครพบปัญหาอะไรและในบริบทใด โดยยังไม่ล็อกวิธีแก้ ประโยคที่เริ่มด้วยเราจะช่วยให้ผู้ใช้ทำสิ่งใดได้อย่างไร เปิดทางให้สำรวจหลายแนวทาง', 'จัดลำดับโอกาสจากผลกระทบ ความมั่นใจของหลักฐาน และแรงที่ต้องใช้ คะแนนเป็นเครื่องมือสนทนา ไม่ใช่ความจริงแน่นอน แยกงานที่ควรทดลองก่อนออกจากงานที่มีหลักฐานพอให้ลงมือ', 'แทนโจทย์สร้าง chatbot ใช้โจทย์ช่วยผู้สมัครทราบสถานะหลังชำระเงิน วิธีแก้อาจเป็นหน้าสถานะ อีเมล หรือข้อความในใบเสร็จ', 'เขียนโจทย์จากปัญหารอรับสินค้าโดยไม่ทราบเวลา และเสนอวิธีแก้สองแบบ', 'เราจะช่วยลูกค้าวางแผนระหว่างรอรับสินค้าได้อย่างไร: แสดงช่วงเวลารอโดยประมาณ หรือแจ้งเตือนเมื่อใกล้ถึงคิว ทดลองว่าผู้ใช้เข้าใจความไม่แน่นอนของเวลาอย่างไร'),
    ('Service Design Essentials', 'Lesson 5', 'Sub-lesson 1', 5, 1, 'Service Prototyping', 'เลือกต้นแบบที่ทดสอบข้อสงสัยได้โดยใช้ทรัพยากรน้อย', 'ต้นแบบบริการอาจเป็นบทสนทนาจำลอง กระดาษ หรือการให้คนทำงานแทนระบบชั่วคราว เป้าหมายคือเรียนรู้จากปฏิกิริยาของผู้ใช้ ไม่จำเป็นต้องสร้างระบบทั้งหมดให้เสร็จก่อน', 'เขียนสมมติฐานหนึ่งข้อ เลือกสถานการณ์ทดสอบ และกำหนดสิ่งที่จะสังเกต ให้ผู้ใช้ลองทำโดยไม่สอนทุกขั้นตอน หลังจบทดลองถามเหตุผลและบันทึกสิ่งที่ต้องปรับ', 'ก่อนสร้างระบบแจ้งคิว ทีมใช้บัตรคิวกระดาษและให้พนักงานส่งข้อความทดลอง เพื่อดูว่าลูกค้าเข้าใจเวลาและจุดรับสินค้าหรือไม่', 'ออกแบบการทดสอบต้นแบบแจ้งคิวหนึ่งครั้ง ระบุสมมติฐาน งานของผู้ใช้ และสิ่งที่สังเกต', 'สมมติฐาน: ข้อความพร้อมแผนที่ช่วยให้รับของถูกจุด งาน: อ่านข้อความแล้วไปจุดรับ สังเกตการถามทางและจุดที่ลังเล ไม่สรุปผลแทนผู้ใช้จากความชอบข้อความเพียงอย่างเดียว'),
    ('Service Design Essentials', 'Lesson 6', 'Sub-lesson 1', 6, 1, 'Service Blueprint and Improvement', 'เชื่อมประสบการณ์ด้านหน้ากับงานเบื้องหลังได้', 'Service blueprint เชื่อมการกระทำผู้ใช้ งานที่ผู้ใช้มองเห็น งานเบื้องหลัง และระบบสนับสนุน ทำให้ทีมเห็นว่าใครรับผิดชอบแต่ละช่วงและปัญหาหนึ่งจุดส่งผลต่อจุดอื่นอย่างไร', 'เลือก journey หนึ่งเส้นทาง วางงานด้านหน้าและเบื้องหลังให้ตรงกัน ระบุจุดส่งต่องาน เจ้าของงาน และตัวชี้วัด จากนั้นเลือกการปรับปรุงเล็ก ๆ พร้อมติดตามผลก่อนขยาย', 'เมื่อลูกค้ากดสั่งกาแฟ งานด้านหน้าคือยืนยันคำสั่งซื้อ งานเบื้องหลังคือส่งคิวให้บาริสต้า ระบบสนับสนุนคือรายการสินค้าและสถานะการชำระเงิน', 'ทำ blueprint ย่อของการคืนสินค้า พร้อมระบุจุดเสี่ยงและตัวชี้วัดหนึ่งตัว', 'ลูกค้ายื่นคำขอ → เจ้าหน้าที่แจ้งขั้นตอน → คลังตรวจสินค้า → ระบบคืนเงิน จุดเสี่ยงคือคลังไม่ส่งผลตรวจ วัดเวลาตั้งแต่รับของคืนจนแจ้งผลลูกค้า และกำหนดเจ้าของการติดตาม'),
    ('Software Developer', 'Introduction to Programming', 'Introduction to Programming', 1, 1, 'Introduction to Programming', 'อธิบาย input, process และ output ของโปรแกรมได้', 'โปรแกรมคือคำสั่งที่คอมพิวเตอร์ทำตามเพื่อแปลงข้อมูลเข้าเป็นผลลัพธ์ การแก้ปัญหาเริ่มจากกำหนดข้อมูลที่มี กฎที่ใช้ และผลลัพธ์ที่ต้องการ ก่อนเลือกภาษาเขียนโปรแกรม', 'แตกงานใหญ่เป็นขั้นตอนเล็ก เขียนขั้นตอนเป็นภาษาธรรมดา แล้วลองทำด้วยข้อมูลตัวอย่าง ถ้าขั้นตอนกำกวมหรือขาดเงื่อนไข ควรแก้ก่อนแปลงเป็นโค้ด', 'คำนวณราคาสมุด: รับราคา 40 บาทและจำนวน 3 เล่ม คูณ 40 × 3 แล้วแสดงยอด 120 บาท ข้อมูลเข้าและผลลัพธ์ต้องมีหน่วยชัดเจน', 'เขียนขั้นตอนคำนวณค่าเฉลี่ยคะแนน 3 วิชา พร้อมลองด้วย 60, 75 และ 90', 'รับคะแนนทั้งสาม → ตรวจว่าเป็นตัวเลข → รวมได้ 225 → หารด้วย 3 → แสดงค่าเฉลี่ย 75 หากข้อมูลไม่ใช่ตัวเลขควรแจ้งให้แก้ไขก่อนคำนวณ'),
    ('Software Developer', 'Development Tools', 'Development Tools', 2, 1, 'Development Tools', 'แยกหน้าที่ของ editor, terminal และ version control ได้', 'Editor ใช้เขียนไฟล์ Terminal ใช้เรียกคำสั่ง และ version control ใช้บันทึกประวัติการเปลี่ยนแปลง เครื่องมือเหล่านี้ช่วยให้ทำงานซ้ำ ตรวจปัญหา และย้อนดูเหตุผลของการแก้ไขได้', 'สร้างโฟลเดอร์งานและไฟล์ README อธิบายวิธีเริ่มต้น ก่อนบันทึกงานตรวจความต่างของไฟล์เสมอ รวมการเปลี่ยนแปลงที่เกี่ยวข้องไว้ด้วยกัน และอย่าใส่รหัสผ่านลงในประวัติโค้ด', 'เมื่อเพิ่มสูตรคำนวณราคา ให้ตรวจเฉพาะไฟล์สูตรและตัวอย่างใช้งานก่อนบันทึก แทนการรวมไฟล์ทดลองที่ไม่เกี่ยวข้องไปด้วย', 'ร่าง README สั้น ๆ สำหรับโปรแกรมค่าเฉลี่ย ระบุหน้าที่ ข้อมูลเข้า และวิธีตรวจผล', 'README ควรบอกว่าโปรแกรมคำนวณค่าเฉลี่ยสามคะแนน รับเฉพาะตัวเลข และมีตัวอย่าง 60,75,90 → 75 ผู้อื่นควรทำตามแล้วได้ผลเดิม'),
    ('Software Developer', 'Variables and Data Types', 'Variables and Data Types', 3, 1, 'Variables and Data Types', 'เลือกชนิดข้อมูลให้สอดคล้องกับความหมายได้', 'ตัวแปรเป็นชื่ออ้างอิงข้อมูล ชนิดข้อมูลพื้นฐานประกอบด้วยตัวเลข ข้อความ และค่าจริงหรือเท็จ ตัวเลขที่ใช้คำนวณต่างจากข้อความที่มีแต่ตัวเลข เช่น รหัสนักเรียนซึ่งอาจขึ้นต้นด้วยศูนย์', 'ตั้งชื่อตามความหมาย ตรวจชนิดข้อมูลที่รับเข้ามาก่อนใช้ และแปลงชนิดอย่างตั้งใจ ใน JavaScript การบวกข้อความกับตัวเลขอาจต่อข้อความแทนการคำนวณ', 'const price = 40; const quantity = 3; const total = price * quantity; ได้ 120 แต่ "40" + 3 ได้ข้อความ "403"', 'เลือกชนิดข้อมูลสำหรับรหัส "0012", ราคา 99.5 และสถานะชำระแล้ว พร้อมอธิบาย', 'รหัสเป็น string เพื่อเก็บศูนย์ด้านหน้า ราคาเป็น number สำหรับคำนวณในตัวอย่าง และสถานะเป็น boolean เช่น true หลีกเลี่ยงข้อความ "true" หากต้องตรวจเงื่อนไขแบบ boolean'),
    ('Software Developer', 'Control Flow', 'Control Flow', 4, 1, 'Control Flow', 'ใช้เงื่อนไขและการวนซ้ำแก้ปัญหาได้', 'เงื่อนไขเลือกว่าจะทำคำสั่งใด ส่วนการวนซ้ำทำชุดคำสั่งกับข้อมูลหลายรายการ ทุกเงื่อนไขควรครอบคลุมค่าขอบเขต และทุกลูปควรมีเงื่อนไขที่ทำให้หยุดได้', 'เขียนกฎด้วยคำพูดก่อน เช่น คะแนนตั้งแต่ 50 ถือว่าผ่าน แล้วทดสอบค่าที่ต่ำกว่า เท่ากับ และสูงกว่าขอบเขต สำหรับลูปให้ลองทั้งรายการว่างและหลายรายการ', 'if (score >= 50) แยกคะแนนผ่านได้ถูกต้องที่ 50 สำหรับคะแนน [40,50,80] การวนตรวจทีละตัวจะพบผู้ผ่าน 2 คน', 'ออกแบบกรณีทดสอบส่วนลดที่เริ่มเมื่อยอดซื้ออย่างน้อย 1000 บาท', 'ทดสอบ 999 ว่าไม่ลด, 1000 ว่าลด และ 1001 ว่าลด เพิ่มกรณียอดติดลบเพื่อกำหนดว่าจะปฏิเสธข้อมูลอย่างไร ไม่เปลี่ยนกฎเป็นมากกว่า 1000 โดยไม่ตั้งใจ'),
    ('Software Developer', 'Functions and Modules', 'Functions and Modules', 5, 1, 'Functions and Modules', 'แยกฟังก์ชันที่มีหน้าที่ชัดเจนและทดสอบได้', 'ฟังก์ชันรวมขั้นตอนที่ทำหน้าที่หนึ่งอย่าง รับพารามิเตอร์และส่งค่ากลับ ส่วน module จัดกลุ่มโค้ดที่เกี่ยวข้อง การแยกส่วนช่วยให้เปลี่ยนกฎหนึ่งจุดโดยไม่ต้องแก้ซ้ำหลายแห่ง', 'เริ่มจากแยกการคำนวณออกจากการแสดงผล ระบุ input และ output ให้ชัด ฟังก์ชันที่ไม่แก้ข้อมูลภายนอกมักทดสอบง่าย เพราะข้อมูลเข้าเดิมให้ผลเดิม', 'function total(price, quantity) { return price * quantity } ใช้คำนวณได้โดยไม่ผูกกับปุ่มหรือหน้าเว็บ เรียก total(40, 3) ได้ 120', 'ร่างฟังก์ชันหาค่าเฉลี่ยจากรายการตัวเลข และกำหนดผลสำหรับรายการว่าง', 'รวมค่าทั้งหมดแล้วหารจำนวนสมาชิก หากรายการว่างอาจคืน null โดยต้องบอกผู้เรียกให้ชัด ทดสอบ [2,4] → 3, [5] → 5 และ [] → null'),
    ('Software Developer', 'Build a Project', 'Build a Project', 6, 1, 'Build a Project', 'วางขอบเขตและตรวจรับโปรเจกต์ขนาดเล็กได้', 'โปรเจกต์เริ่มต้นควรเล็กพอที่จะทำครบทั้งรับข้อมูล ประมวลผล แสดงผล และจัดการข้อผิดพลาด การทำเส้นทางใช้งานหลักให้ครบมีประโยชน์กว่าการเพิ่มหลายฟีเจอร์ที่ยังไม่เชื่อมกัน', 'เขียนสิ่งที่ผู้ใช้ทำได้และเกณฑ์ยอมรับ สร้างทีละส่วน ทดสอบกรณีปกติและข้อมูลไม่ถูกต้อง แล้วให้ผู้อื่นทำตาม README โดยไม่ช่วย เพื่อหาขั้นตอนที่ตกหล่น', 'แอปรายการงานรุ่นแรกมีเพิ่มงาน ทำเครื่องหมายเสร็จ และลบงาน เกณฑ์หนึ่งคือข้อความว่างเพิ่มไม่ได้ และทำเครื่องหมายงานหนึ่งต้องไม่เปลี่ยนงานอื่น', 'เขียนเกณฑ์ยอมรับ 3 ข้อสำหรับแอปรายการงาน พร้อมกรณีทดสอบอย่างน้อยหนึ่งกรณีต่อข้อ', 'เพิ่มชื่อที่ไม่ว่างแล้วปรากฏหนึ่งรายการ; กดเสร็จที่งาน A แล้ว B ไม่เปลี่ยน; ลบ A แล้วเหลือ B ตรวจเพิ่มด้วยชื่อที่มีแต่ช่องว่าง และอธิบายว่าข้อมูลคงอยู่หลังรีเฟรชหรือไม่'),
    ('UX/UI Design Beginner', 'Design Foundations', 'Design Foundations', 1, 1, 'Design Foundations', 'แยก UX, UI และลำดับความสำคัญของข้อมูลได้', 'UX ครอบคลุมประสบการณ์การใช้งานเพื่อบรรลุเป้าหมาย ส่วน UI คือส่วนติดต่อที่ผู้ใช้เห็นและโต้ตอบ ความสวยเพียงอย่างเดียวไม่รับรองว่าผู้ใช้จะเข้าใจขั้นตอนหรือทำงานสำเร็จ', 'ระบุงานหลักของหน้าจอหนึ่งอย่าง จัดหัวข้อ ข้อความ และปุ่มตามความสำคัญ ใช้ความสม่ำเสมอช่วยให้คาดเดาได้ และอย่าใช้สีเพียงอย่างเดียวสื่อสถานะ', 'หน้าชำระเงินควรเห็นยอดรวม รายการสินค้า และปุ่มยืนยันเด่นชัด ข้อผิดพลาดควรมีข้อความอธิบาย ไม่ใช่แค่กรอบสีแดง', 'จัดลำดับข้อมูลบนหน้าสมัครคอร์ส 4 รายการและอธิบายเหตุผล', 'ชื่อคอร์สและผลที่จะได้ช่วยยืนยันว่ามาถูกหน้า ราคาและเงื่อนไขช่วยตัดสินใจ รายละเอียดสนับสนุนความเข้าใจ และปุ่มสมัครควรอยู่ในบริบทที่เห็นค่าใช้จ่ายแล้ว'),
    ('UX/UI Design Beginner', 'User Research', 'User Research', 2, 1, 'User Research', 'ตั้งคำถามเพื่อเข้าใจพฤติกรรมแทนการขอความเห็นลอย ๆ', 'การวิจัยผู้ใช้ช่วยตรวจสมมติฐานเกี่ยวกับปัญหา คำถามเกี่ยวกับเหตุการณ์ที่เกิดขึ้นจริงมักให้รายละเอียดมากกว่าการถามว่าจะใช้ฟีเจอร์สมมติหรือไม่', 'เลือกคนที่มีประสบการณ์เกี่ยวข้อง ขอให้เล่าครั้งล่าสุด และถามต่อถึงขั้นตอนหรือสิ่งที่ติดขัด แยกคำพูดที่บันทึกได้ออกจากการตีความของทีม', 'แทนถามว่าชอบแอปเรียนแบบใหม่ไหม ให้ถามว่าครั้งล่าสุดเลือกคอร์สอย่างไร เปรียบเทียบอะไร และหยุดตรงไหน', 'เขียนคำถามสัมภาษณ์สามข้อสำหรับคนที่เคยซื้อคอร์สออนไลน์', 'ครั้งล่าสุดเริ่มค้นหาจากที่ไหน; ใช้ข้อมูลใดเปรียบเทียบ; มีช่วงใดที่เกือบไม่ซื้อ ขอรายละเอียดเหตุการณ์ต่อแทนการชี้นำว่าราคาหรือหน้าจอเป็นปัญหา'),
    ('UX/UI Design Beginner', 'Wireframing', 'Wireframing', 3, 1, 'Wireframing', 'ร่างหน้าจอจากงานของผู้ใช้ก่อนตกแต่งได้', 'Wireframe เป็นโครงร่างที่แสดงตำแหน่งข้อมูลและการกระทำโดยลดรายละเอียดภาพ ช่วยให้คุยเรื่องโครงสร้างและลำดับขั้นตอนได้เร็วโดยยังไม่ลงทุนกับสีหรือภาพ', 'เขียนเส้นทางใช้งานจากจุดเริ่มถึงผลสำเร็จ แล้วร่างหน้าจอเฉพาะที่จำเป็น รวมสถานะว่าง กำลังโหลด และข้อผิดพลาดด้วย เพราะเป็นส่วนหนึ่งของประสบการณ์จริง', 'เส้นทางเลือกคอร์สประกอบด้วยรายการคอร์ส รายละเอียด และยืนยันสมัคร สถานะค้นหาไม่พบต้องมีคำแนะนำให้เปลี่ยนคำค้น ไม่ปล่อยหน้าว่าง', 'ร่าง wireframe หน้ารายการคอร์ส พร้อมสถานะไม่มีผลลัพธ์', 'ควรมีหัวข้อ ช่องค้นหา รายการพร้อมชื่อและราคา และลิงก์ดูรายละเอียด เมื่อไม่พบผลให้แสดงคำค้นที่ใช้และปุ่มล้างตัวกรอง ไม่แสดงปุ่มสมัครที่ไม่มีคอร์ส'),
    ('UX/UI Design Beginner', 'Visual Design', 'Visual Design', 4, 1, 'Visual Design', 'ใช้ตัวอักษร ระยะห่าง และสีช่วยอ่านข้อมูลได้', 'ลำดับชั้นทางสายตาช่วยให้ผู้ใช้รู้ว่าจะอ่านอะไรก่อน ขนาดและน้ำหนักตัวอักษร ระยะห่าง และความแตกต่างของสีควรสนับสนุนหน้าที่ของข้อมูล ไม่แข่งขันกันทุกจุด', 'กำหนดรูปแบบหัวข้อ เนื้อหา และป้ายกำกับที่ใช้ซ้ำ จัดกลุ่มสิ่งที่เกี่ยวข้องด้วยระยะห่าง ตรวจข้อความบนพื้นหลังจริง และใช้ข้อความหรือสัญลักษณ์ร่วมกับสีเมื่อสื่อสถานะ', 'การ์ดคอร์สใช้ชื่อเป็นหัวข้อเด่น คำอธิบายเป็นเนื้อหารอง และราคาใกล้ปุ่มสมัคร สถานะเรียนจบมีทั้งไอคอนและคำว่าเรียนจบ', 'ปรับการ์ดที่มีตัวหนังสือขนาดเท่ากันทั้งหมด โดยระบุการเปลี่ยนแปลงสามอย่าง', 'เพิ่มน้ำหนักชื่อคอร์ส ลดความเด่นของข้อมูลรอง และเว้นกลุ่มราคากับปุ่มให้ชัด ตรวจว่าข้อความยังอ่านได้เมื่อย่อหน้าจอและไม่ตัดข้อมูลสำคัญ'),
    ('UX/UI Design Beginner', 'Interactive Prototypes', 'Interactive Prototypes', 5, 1, 'Interactive Prototypes', 'เชื่อมหน้าจอเป็นต้นแบบที่ใช้ทดสอบงานได้', 'ต้นแบบโต้ตอบจำลองการกดและการเปลี่ยนสถานะเพื่อทดสอบเส้นทางใช้งาน ไม่จำเป็นต้องเชื่อมฐานข้อมูลจริง แต่ต้องตอบสนองในจุดที่จำเป็นต่อคำถามที่ทดสอบ', 'กำหนดจุดเริ่ม เป้าหมาย และเส้นทางที่รองรับ ใส่ทางย้อนกลับและผลลัพธ์หลังการกระทำ ระบุข้อจำกัดของต้นแบบให้ผู้ทดสอบทราบโดยไม่บอกวิธีทำงานล่วงหน้า', 'ผู้ทดสอบเลือกคอร์ส เปิดรายละเอียด แล้วสมัครสำเร็จ ต้นแบบควรแสดงชื่อคอร์สเดิมตลอดเส้นทางเพื่อไม่ให้สับสนว่าซื้ออะไร', 'เขียนสถานะและการเปลี่ยนหน้าสำหรับการบันทึกคอร์สที่สนใจ', 'ยังไม่บันทึก → กดบันทึก → แสดงสถานะบันทึกแล้ว → เปิดรายการที่สนใจแล้วพบคอร์ส หากกดอีกครั้งควรมีพฤติกรรมยกเลิกที่สม่ำเสมอ'),
    ('UX/UI Design Beginner', 'Usability Testing', 'Usability Testing', 6, 1, 'Usability Testing', 'สังเกตปัญหาการใช้งานและจัดลำดับการแก้ได้', 'Usability testing ให้ผู้ใช้ลองทำงานกับสิ่งที่ออกแบบและสังเกตสิ่งที่เกิดขึ้น งานทดสอบควรบอกเป้าหมายโดยไม่ระบุปุ่มที่จะกด เพื่อให้เห็นว่าผู้ใช้เข้าใจเองหรือไม่', 'จดการทำสำเร็จ จุดลังเล และความผิดพลาด ถามเหตุผลหลังเหตุการณ์โดยไม่ตำหนิผู้ใช้ จัดลำดับปัญหาจากผลกระทบและการเกิดซ้ำ แล้วทดสอบแนวทางแก้ต่อ', 'โจทย์ค้นหาคอร์สสำหรับผู้เริ่มต้นและดูราคาดีกว่าโจทย์กดตัวกรอง Beginner เพราะแบบหลังบอกวิธีแก้ไว้แล้ว', 'เขียนงานทดสอบหนึ่งข้อและแบบบันทึกผลสามช่องสำหรับหน้าค้นหาคอร์ส', 'งาน: หาคอร์สออกแบบสำหรับคนไม่มีพื้นฐานในงบที่กำหนด ช่องบันทึก: สำเร็จหรือไม่, สิ่งที่สังเกต, คำพูดผู้ใช้ แยกข้อเสนอของผู้วิจัยออกจากหลักฐาน'),
    ('Service Design Essentials', 'Lesson 1', 'Course Overview', 1, 2, 'Course Overview', 'อธิบายเส้นทางการเรียนและสิ่งที่จะได้ฝึกในคอร์สนี้ได้', 'คอร์สนี้เริ่มจากความหมายของการออกแบบบริการ แล้วค่อยสำรวจผู้ใช้ หลักการทำงานร่วมกัน และวิธีปรับปรุงบริการ การอ่านแต่ละบทตามลำดับช่วยให้เชื่อมแนวคิดใหม่เข้ากับสถานการณ์ใกล้ตัวได้', 'ก่อนเริ่มให้เลือกบริการหนึ่งอย่างที่คุ้นเคยไว้เป็นกรณีศึกษา หลังจบแต่ละบท ลองกลับมาดูบริการเดิมว่ามองเห็นผู้ใช้ จุดสัมผัส และงานเบื้องหลังเพิ่มเติมอย่างไร', 'หากเลือกบริการร้านกาแฟ บทแรกอาจมองขั้นตอนสั่งซื้อ ต่อมาจึงสำรวจช่วงรอรับสินค้าและการประสานงานของพนักงาน', 'เลือกบริการหนึ่งอย่างและเขียนสิ่งที่อยากเข้าใจเพิ่มหลังเรียนจบคอร์สนี้', 'ตัวอย่าง: เลือกร้านกาแฟและอยากรู้ว่าจุดใดทำให้ลูกค้ารอนาน รวมถึงพนักงานใช้ข้อมูลใดจัดลำดับคำสั่งซื้อ'),
    ('Service Design Essentials', 'Lesson 1', 'Getting to Know You', 1, 3, 'Getting to Know You', 'ระบุประสบการณ์และเป้าหมายของตนก่อนเริ่มเรียนได้', 'ผู้เรียนแต่ละคนมีพื้นฐานต่างกัน บางคนเคยออกแบบหน้าจอ บางคนทำงานหน้าร้านหรือดูแลกระบวนการ การรู้ว่าตนคุ้นเคยกับส่วนไหนช่วยให้เลือกตัวอย่างและตั้งคำถามที่ตรงกับการใช้งานจริง', 'ลองเขียนบทบาทที่เคยทำ บริการที่พบเป็นประจำ และปัญหาหนึ่งอย่างที่อยากแก้ โดยแยกสิ่งที่เคยสังเกตจริงออกจากสิ่งที่คาดเดาไว้', 'คนที่เคยรับออร์เดอร์อาจสังเกตว่าลูกค้าถามสถานะบ่อย แต่ยังไม่รู้ว่าปัญหาเกิดจากเวลารอหรือการสื่อสารที่ไม่ชัด', 'เขียนประสบการณ์เดิมหนึ่งข้อและคำถามที่อยากหาคำตอบระหว่างเรียนหนึ่งข้อ', 'ตัวอย่าง: เคยดูแลลูกค้าหน้าร้านและอยากรู้ว่าจะแจ้งเวลารออย่างไรให้ลูกค้าเข้าใจโดยไม่เพิ่มงานให้พนักงาน'),
    ('Service Design Essentials', 'Lesson 1', 'What is Service Design ?', 1, 4, 'What is Service Design ?', 'อธิบายการออกแบบบริการผ่านประสบการณ์ของผู้ใช้ทั้งเส้นทางได้', 'การออกแบบบริการมองสิ่งที่ผู้ใช้ทำและสิ่งที่องค์กรต้องจัดการร่วมกัน ไม่ได้จำกัดอยู่ที่หน้าจอหรือจุดสัมผัสเดียว ผลลัพธ์ที่ดีต้องช่วยให้ผู้ใช้บรรลุเป้าหมายและให้ทีมส่งมอบบริการได้จริง', 'เริ่มจากเป้าหมายผู้ใช้ จากนั้นไล่ช่วงก่อน ระหว่าง และหลังใช้บริการ พร้อมจดผู้เกี่ยวข้องและระบบสนับสนุนในแต่ละช่วง วิธีนี้ช่วยหาปัญหาที่แก้ด้วยการเปลี่ยนกระบวนการแทนการเพิ่มหน้าจอ', 'การรับอาหารเดลิเวอรีเกี่ยวข้องกับหน้าสั่งซื้อ ร้านอาหาร คนส่ง และการแจ้งสถานะ หากอาหารมาถึงช้า ปัญหาอาจอยู่ที่การส่งต่องานระหว่างฝ่าย', 'เลือกบริการหนึ่งอย่างและระบุจุดสัมผัสสองจุดพร้อมงานเบื้องหลังหนึ่งอย่าง', 'ตัวอย่าง: ร้านกาแฟมีจุดสัมผัสคือเมนูและจุดรับเครื่องดื่ม งานเบื้องหลังคือการส่งคำสั่งซื้อให้บาริสต้าตามลำดับคิว');
